{"command":"cat > /tmp/t/server.py <<'EOF'
import socket, sys, threading, os
# usage: server.py port respfile
# respfile contains hex of response (txid will be replaced). If file 'respfile.tcp' exists, it's used for TCP.
port = int(sys.argv[1]); respfile = sys.argv[2]
def load(proto):
    p = respfile + ('.tcp' if proto == 'tcp' and os.path.exists(respfile + '.tcp') else '')
    with open(p) as f:
        return bytes.fromhex(''.join(f.read().split()))
def mk(data, proto):
    r = bytearray(load(proto))
    if len(r) >= 2 and not os.path.exists(respfile + '.keepid'):
        r[0:2] = data[0:2]
    return bytes(r)
def udp():
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    s.bind(('127.0.0.1', port))
    while True:
        data, addr = s.recvfrom(65535)
        print("UDP", len(data), data.hex(), flush=True)
        r = mk(data, 'udp')
        if r: s.sendto(r, addr)
def tcp():
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    s.bind(('127.0.0.1', port)); s.listen(5)
    while True:
        c, addr = s.accept()
        try:
            hdr = c.recv(2)
            if len(hdr) < 2: c.close(); continue
            n = int.from_bytes(hdr, 'big')
            data = b''
            while len(data) < n:
                chunk = c.recv(n - len(data))
                if not chunk: break
                data += chunk
            print("TCP", len(data), data.hex(), flush=True)
            r = mk(data, 'tcp')
            if r: c.sendall(len(r).to_bytes(2, 'big') + r)
        except Exception as e:
            print("ERR", e, flush=True)
        c.close()
threading.Thread(target=udp, daemon=True).start()
tcp()
EOF
cat > /tmp/t/mkresp.py <<'EOF'
# Build DNS response packets from a simple python spec
import struct, sys
def name(s):
    if s in ('', '.'): return b'\x00'
    out = b''
    for label in s.rstrip('.').split('.'):
        out += bytes([len(label)]) + label.encode()
    return out + b'\x00'
def rr(nm, typ, cls, ttl, rdata):
    return name(nm) + struct.pack('>HHIH', typ, cls, ttl, len(rdata)) + rdata
def pkt(txid=0x1234, flags=0x8180, q=None, an=(), ns=(), ar=()):
    out = struct.pack('>HHHHHH', txid, flags, 1 if q else 0, len(an), len(ns), len(ar))
    if q:
        out += name(q[0]) + struct.pack('>HH', q[1], q[2])
    for r in list(an)+list(ns)+list(ar): out += r
    return out
EOF
echo ok"}

