{"command":"cat > /tmp/t/tlsserver.py <<'EOF'
import socket, ssl, sys, threading, os
sys.path.insert(0, '/tmp/t')
from mkresp import *
port = int(sys.argv[1]); cert = sys.argv[2]; key = sys.argv[3]; mode = sys.argv[4] if len(sys.argv) > 4 else 'dot'
ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
ctx.load_cert_chain(cert, key)
s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
s.bind(('127.0.0.1', port)); s.listen(5)
def resp(q):
    r = bytearray(pkt(q=('example.com',1,1), an=[rr('example.com',1,1,3600, b'\x05\x06\x07\x08')])); r[0:2] = q[0:2]
    return bytes(r)
def handle(c):
    try:
        t = ctx.wrap_socket(c, server_side=True)
        print("TLS version", t.version(), "SNI", getattr(t, 'server_hostname', None), flush=True)
        if mode == 'dot':
            hdr = t.recv(2); n = int.from_bytes(hdr, 'big'); data = b''
            while len(data) < n: data += t.recv(n - len(data))
            print("DOT query", data.hex(), flush=True)
            r = resp(data)
            t.sendall(len(r).to_bytes(2,'big') + r)
        else:
            data = b''
            while b'\r\n\r\n' not in data:
                chunk = t.recv(65535)
                if not chunk: break
                data += chunk
            head, _, body = data.partition(b'\r\n\r\n')
            print("HTTP request head:", repr(head), flush=True)
            clen = 0
            for line in head.split(b'\r\n'):
                if line.lower().startswith(b'content-length:'): clen = int(line.split(b':')[1])
            while len(body) < clen: body += t.recv(clen - len(body))
            print("HTTP body:", body.hex(), flush=True)
            with open('/tmp/t/dohmode') as f: dm = f.read().strip()
            r = resp(body) if body else b''
            if dm == 'ok':
                out = b'HTTP/1.1 200 OK\r\nContent-Type: application/dns-message\r\nContent-Length: %d\r\n\r\n' % len(r) + r
            elif dm == 'nolen':
                out = b'HTTP/1.1 200 OK\r\nContent-Type: application/dns-message\r\nConnection: close\r\n\r\n' + r
            elif dm == '404':
                out = b'HTTP/1.1 404 Not Found\r\nContent-Type: text/plain\r\nContent-Length: 9\r\n\r\nnot found'
            elif dm == '500':
                out = b'HTTP/1.1 500 Internal Server Error\r\nContent-Length: 0\r\n\r\n'
            elif dm == 'badct':
                out = b'HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: %d\r\n\r\n' % len(r) + r
            elif dm == 'chunked':
                out = b'HTTP/1.1 200 OK\r\nContent-Type: application/dns-message\r\nTransfer-Encoding: chunked\r\n\r\n' + ('%x' % len(r)).encode() + b'\r\n' + r + b'\r\n0\r\n\r\n'
            elif dm == 'garbage':
                out = b'blah blah\r\n\r\n'
            elif dm == 'http10':
                out = b'HTTP/1.0 200 OK\r\nContent-Length: %d\r\n\r\n' % len(r) + r
            elif dm == 'extra':
                out = b'HTTP/1.1 200 OK\r\nContent-Length: %d\r\nX-Foo: bar\r\n\r\n' % len(r) + r + b'EXTRA'
            elif dm == 'shortbody':
                out = b'HTTP/1.1 200 OK\r\nContent-Length: %d\r\n\r\n' % (len(r)+10) + r
            else:
                out = b''
            t.sendall(out)
        t.close()
    except Exception as e:
        print("ERR", repr(e), flush=True)
while True:
    c, addr = s.accept()
    threading.Thread(target=handle, args=(c,), daemon=True).start()
EOF
