//! Minimal logger that mimics the style of pretty-env-logger output.
//! Activated by the `DOG_DEBUG` environment variable.

use std::fmt::Arguments;
use std::sync::atomic::{AtomicU8, Ordering};

static LEVEL: AtomicU8 = AtomicU8::new(0);

#[derive(PartialEq, Clone, Copy)]
pub enum Level {
    Trace,
    Debug,
    Info,
    Warn,
    Error,
}

pub fn init() {
    if let Some(value) = std::env::var_os("DOG_DEBUG") {
        if value.is_empty() {
            LEVEL.store(0, Ordering::Relaxed);
        } else if value == "trace" {
            LEVEL.store(2, Ordering::Relaxed);
        } else {
            LEVEL.store(1, Ordering::Relaxed);
        }
    }
}

pub fn enabled(level: Level) -> bool {
    let l = LEVEL.load(Ordering::Relaxed);
    if l == 0 {
        return false;
    }
    if l == 1 && level == Level::Trace {
        return false;
    }
    true
}

pub fn log(level: Level, target: &str, args: Arguments<'_>) {
    if !enabled(level) {
        return;
    }
    let (name, colour) = match level {
        Level::Trace => ("TRACE", "\x1b[38;5;245m"),
        Level::Debug => ("DEBUG", "\x1b[34m"),
        Level::Info => ("INFO", "\x1b[36m"),
        Level::Warn => ("WARN", "\x1b[33m"),
        Level::Error => ("ERROR", "\x1b[31m"),
    };
    let grey = "\x1b[38;5;243m";
    let reset = "\x1b[0m";
    let line = format!(
        "{grey}[{reset}{colour}{name}{reset} {target}{grey}]{reset} {args}\n",
        grey = grey,
        reset = reset,
        colour = colour,
        name = name,
        target = target,
        args = args
    );
    use std::io::Write;
    let stderr = std::io::stderr();
    let mut lock = stderr.lock();
    let _ = lock.write_all(line.as_bytes());
    let _ = lock.flush();
}

#[macro_export]
macro_rules! log_at {
    ($level:expr, $target:expr, $($arg:tt)*) => {
        if $crate::logger::enabled($level) {
            $crate::logger::log($level, $target, format_args!($($arg)*))
        }
    };
}

#[macro_export]
macro_rules! trace {
    ($target:expr, $($arg:tt)*) => { $crate::log_at!($crate::logger::Level::Trace, $target, $($arg)*) };
}
#[macro_export]
macro_rules! debug {
