{"command":"cd /workspace && cat > src/getopts.rs <<'EOF'
//! A small getopt-style command-line parser, written to behave like the
//! classic Rust `getopts` interface: short and long options, options that
//! take arguments, grouped short flags (`-UT`), `--long=value`, and `--`.

use std::fmt;

#[derive(Clone, Copy, PartialEq)]
pub enum HasArg {
    Yes,
    No,
}

#[derive(Clone, Copy, PartialEq)]
pub enum Occur {
    Optional,
    Multi,
}

#[derive(Clone, PartialEq, Debug)]
pub enum Name {
    Long(String),
    Short(char),
}

impl Name {
    fn from_str(nm: &str) -> Name {
        if nm.chars().count() == 1 {
            Name::Short(nm.chars().next().unwrap())
        } else {
            Name::Long(nm.to_string())
        }
    }

    fn to_string(&self) -> String {
        match self {
            Name::Short(ch) => ch.to_string(),
            Name::Long(s) => s.clone(),
        }
    }
}

struct OptGroup {
    short_name: String,
    long_name: String,
    hasarg: HasArg,
    occur: Occur,
}

struct Opt {
    name: Name,
    hasarg: HasArg,
    occur: Occur,
    aliases: Vec<Name>,
}

impl OptGroup {
    fn long_to_short(&self) -> Opt {
        let short = self.short_name.clone();
        let long = self.long_name.clone();
        match (short.is_empty(), long.is_empty()) {
            (true, true) => panic!("this long-format option was given no name"),
            (false, true) => Opt {
                name: Name::Short(short.chars().next().unwrap()),
                hasarg: self.hasarg,
                occur: self.occur,
                aliases: Vec::new(),
            },
            (true, false) => Opt {
                name: Name::Long(long),
                hasarg: self.hasarg,
                occur: self.occur,
                aliases: Vec::new(),
            },
            (false, false) => Opt {
                name: Name::Long(long),
                hasarg: self.hasarg,
                occur: self.occur,
                aliases: vec![Name::Short(short.chars().next().unwrap())],
            },
        }
    }
}

#[derive(Default)]
pub struct Options {
    grps: Vec<OptGroup>,
}

#[derive(Clone, PartialEq, Debug)]
enum Optval {
    Val(String),
    Given,
}

pub struct Matches {
    opts: Vec<(Name, Vec<Name>)>,
    vals: Vec<Vec<(usize, Optval)>>,
    pub free: Vec<String>,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Fail {
    ArgumentMissing(String),
    UnrecognizedOption(String),
    OptionMissing(String),
    OptionDuplicated(String),
    UnexpectedArgument(String),
}

impl fmt::Display for Fail {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Fail::ArgumentMissing(nm) => write!(f, "Argument to option '{}' missing", nm),
            Fail::UnrecognizedOption(nm) => write!(f, "Unrecognized option: '{}'", nm),
            Fail::OptionMissing(nm) => write!(f, "Required option '{}' missing", nm),
            Fail::OptionDuplicated(nm) => write!(f, "Option '{}' given more than once", nm),
            Fail::UnexpectedArgument(nm) => write!(f, "Option '{}' does not take an argument", nm),
        }
    }
}

fn is_arg(arg: &str) -> bool {
    arg.as_bytes().first() == Some(&b'-') && arg.len() > 1
}

fn find_opt(opts: &[Opt], nm: &Name) -> Option<usize> {
    if let Some(pos) = opts.iter().position(|opt| &opt.name == nm) {
        return Some(pos);
    }
    for candidate in opts.iter() {
        if candidate.aliases.iter().any(|alias| alias == nm) {
            return opts.iter().position(|opt| opt.name == candidate.name);
        }
    }
    None
}

impl Options {
    pub fn new() -> Options {
        Options { grps: Vec::new() }
    }

    fn add(&mut self, short: &str, long: &str, hasarg: HasArg, occur: Occur) -> &mut Options {
        self.grps.push(OptGroup {
            short_name: short.to_string(),
            long_name: long.to_string(),
            hasarg,
            occur,
        });
        self
    }

    pub fn optflag(&mut self, short: &str, long: &str) -> &mut Options {
        self.add(short, long, HasArg::No, Occur::Optional)
    }

    pub fn optopt(&mut self, short: &str, long: &str) -> &mut Options {
        self.add(short, long, HasArg::Yes, Occur::Optional)
    }

    pub fn optmulti(&mut self, short: &str, long: &str) -> &mut Options {
        self.add(short, long, HasArg::Yes, Occur::Multi)
    }

    pub fn parse<I: IntoIterator<Item = String>>(&self, args: I) -> Result<Matches, Fail> {
        let opts: Vec<Opt> = self.grps.iter().map(|g| g.long_to_short()).collect();
        let mut vals: Vec<Vec<(usize, Optval)>> = (0..opts.len()).map(|_| Vec::new()).collect();
        let mut free: Vec<String> = Vec::new();
        let args: Vec<String> = args.into_iter().collect();
        let mut args = args.into_iter().peekable();
        let mut arg_pos = 0;

        while let Some(cur) = args.next() {
            if !is_arg(&cur) {
                free.push(cur);
            } else if cur == "--" {
                free.extend(args);
                break;
            } else {
                let mut names: Vec<Name>;
                let mut i_arg: Option<String> = None;
                let mut was_long = true;
                if cur.as_bytes()[1] == b'-' {
                    let tail = &cur[2..];
                    let mut parts = tail.splitn(2, '=');
                    names = vec![Name::from_str(parts.next().unwrap())];
                    if let Some(rest) = parts.next() {
                        i_arg = Some(rest.to_string());
                    }
                } else {
                    was_long = false;
                    names = Vec::new();
                    for (j, ch) in cur.char_indices().skip(1) {
                        let opt = Name::Short(ch);
                        let opt_id = match find_opt(&opts, &opt) {
                            Some(id) => id,
                            None => return Err(Fail::UnrecognizedOption(opt.to_string())),
                        };
                        names.push(opt);
                        let arg_follows = opts[opt_id].hasarg == HasArg::Yes;
                        if arg_follows {
                            let next = j + ch.len_utf8();
                            if next < cur.len() {
                                i_arg = Some(cur[next..].to_string());
                                break;
                            }
                        }
                    }
                }

                let mut name_pos = 0;
                for nm in names.iter() {
                    name_pos += 1;
                    let optid = match find_opt(&opts, nm) {
                        Some(id) => id,
                        None => return Err(Fail::UnrecognizedOption(nm.to_string())),
                    };
                    match opts[optid].hasarg {
                        HasArg::No => {
                            if name_pos == names.len() && i_arg.is_some() {
                                return Err(Fail::UnexpectedArgument(nm.to_string()));
                            }
                            vals[optid].push((arg_pos, Optval::Given));
                        }
                        HasArg::Yes => {
                            if let Some(i_arg) = i_arg.take() {
                                vals[optid].push((arg_pos, Optval::Val(i_arg)));
                            } else if let Some(n) = args.next() {
                                vals[optid].push((arg_pos, Optval::Val(n)));
                            } else {
                                return Err(Fail::ArgumentMissing(nm.to_string()));
                            }
                        }
                    }
                }
                let _ = was_long;
            }
            arg_pos += 1;
        }

        for (vals, opt) in vals.iter().zip(opts.iter()) {
            if opt.occur != Occur::Multi && vals.len() > 1 {
                return Err(Fail::OptionDuplicated(opt.name.to_string()));
            }
        }

        Ok(Matches {
            opts: opts.into_iter().map(|o| (o.name, o.aliases)).collect(),
            vals,
            free,
        })
    }
}

impl Matches {
    fn opt_vals(&self, nm: &str) -> Vec<(usize, Optval)> {
        let name = Name::from_str(nm);
        match self.opts.iter().position(|(n, aliases)| n == &name || aliases.contains(&name)) {
            Some(id) => self.vals[id].clone(),
            None => panic!("No option '{}' defined", nm),
        }
    }

    pub fn opt_present(&self, nm: &str) -> bool {
        !self.opt_vals(nm).is_empty()
    }

    pub fn opt_str(&self, nm: &str) -> Option<String> {
        match self.opt_vals(nm).into_iter().next() {
            Some((_, Optval::Val(s))) => Some(s),
            _ => None,
        }
    }

    pub fn opt_strs(&self, nm: &str) -> Vec<String> {
        self.opt_vals(nm)
            .into_iter()
            .filter_map(|(_, v)| match v {
                Optval::Val(s) => Some(s),
                Optval::Given => None,
            })
            .collect()
    }
}
EOF
echo done"}

