/// A query class.
#[derive(PartialEq, Debug, Clone, Copy)]
#[allow(clippy::upper_case_acronyms)]
pub enum QClass {
    IN,
    CH,
    HS,
    Other(u16),
}

impl QClass {
    pub fn from_number(num: u16) -> Self {
        match num {
            1 => QClass::IN,
            3 => QClass::CH,
            4 => QClass::HS,
            n => QClass::Other(n),
        }
    }

    pub fn number(self) -> u16 {
        match self {
            QClass::IN => 1,
            QClass::CH => 3,
            QClass::HS => 4,
            QClass::Other(n) => n,
        }
    }

    pub fn name(self) -> Option<&'static str> {
        match self {
            QClass::IN => Some("IN"),
            QClass::CH => Some("CH"),
            QClass::HS => Some("HS"),
            QClass::Other(_) => None,
        }
    }
}

/// The header flags of a DNS packet.
#[derive(PartialEq, Debug, Clone)]
pub struct Flags {
    pub response: bool,
    pub opcode: Opcode,
    pub authoritative: bool,
    pub truncated: bool,
    pub recursion_desired: bool,
    pub recursion_available: bool,
    pub authentic_data: bool,
    pub checking_disabled: bool,
    pub error_code: Option<ErrorCode>,
}

#[derive(PartialEq, Debug, Clone, Copy)]
pub enum Opcode {
    Query,
    Other(u8),
}

#[derive(PartialEq, Debug, Clone, Copy)]
pub enum ErrorCode {
    FormatError,
    ServerFailure,
    NXDomain,
    NotImplemented,
    QueryRefused,
    Other(u16),
}

impl fmt::Display for ErrorCode {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ErrorCode::FormatError => write!(f, "Format Error"),
            ErrorCode::ServerFailure => write!(f, "Server Failure"),
            ErrorCode::NXDomain => write!(f, "NXDomain"),
            ErrorCode::NotImplemented => write!(f, "Not Implemented"),
            ErrorCode::QueryRefused => write!(f, "Query Refused"),
            ErrorCode::Other(n) => write!(f, "Other Failure ({})", n),
        }
    }
}

impl Flags {
    pub fn query() -> Self {
        Flags {
            response: false,
            opcode: Opcode::Query,
            authoritative: false,
            truncated: false,
            recursion_desired: true,
            recursion_available: false,
            authentic_data: false,
            checking_disabled: false,
            error_code: None,
        }
    }

    pub fn to_u16(&self) -> u16 {
        let mut bits = 0u16;
        if self.response {
            bits |= 0b_1000_0000_0000_0000;
        }
        match self.opcode {
            Opcode::Query => {}
            Opcode::Other(n) => bits |= (u16::from(n) & 0xF) << 11,
        }
        if self.authoritative {
            bits |= 0b_0000_0100_0000_0000;
        }
        if self.truncated {
            bits |= 0b_0000_0010_0000_0000;
        }
        if self.recursion_desired {
            bits |= 0b_0000_0001_0000_0000;
        }
        if self.recursion_available {
            bits |= 0b_0000_0000_1000_0000;
        }
        if self.authentic_data {
            bits |= 0b_0000_0000_0010_0000;
        }
        if self.checking_disabled {
            bits |= 0b_0000_0000_0001_0000;
        }
        if let Some(code) = self.error_code {
            let n = match code {
                ErrorCode::FormatError => 1,
                ErrorCode::ServerFailure => 2,
                ErrorCode::NXDomain => 3,
                ErrorCode::NotImplemented => 4,
                ErrorCode::QueryRefused => 5,
                ErrorCode::Other(n) => n,
            };
            bits |= n & 0xF;
        }
        bits
    }

    pub fn from_u16(bits: u16) -> Self {
        let has_bit = |bit: u16| bits & bit == bit;
        let opcode = match ((bits >> 11) & 0xF) as u8 {
            0 => Opcode::Query,
            n => Opcode::Other(n),
        };
        let error_code = match bits & 0xF {
            0 => None,
            1 => Some(ErrorCode::FormatError),
            2 => Some(ErrorCode::ServerFailure),
            3 => Some(ErrorCode::NXDomain),
            4 => Some(ErrorCode::NotImplemented),
            5 => Some(ErrorCode::QueryRefused),
            n => Some(ErrorCode::Other(n)),
        };
        Flags {
            response: has_bit(0b_1000_0000_0000_0000),
            opcode,
            authoritative: has_bit(0b_0000_0100_0000_0000),
            truncated: has_bit(0b_0000_0010_0000_0000),
            recursion_desired: has_bit(0b_0000_0001_0000_0000),
            recursion_available: has_bit(0b_0000_0000_1000_0000),
            authentic_data: has_bit(0b_0000_0000_0010_0000),
            checking_disabled: has_bit(0b_0000_0000_0001_0000),
            error_code,
        }
    }
}

/// A DNS query, as sent or as found in a response.
