/// Decodes a Punycode string (the part after the `xn--` prefix) into a
/// Unicode string, as described in RFC 3492. Returns `None` on failure.
fn punycode_decode(input: &str) -> Option<String> {
    const BASE: u32 = 36;
    const T_MIN: u32 = 1;
    const T_MAX: u32 = 26;
    const SKEW: u32 = 38;
    const DAMP: u32 = 700;
    const INITIAL_BIAS: u32 = 72;
    const INITIAL_N: u32 = 0x80;

    fn adapt(mut delta: u32, num_points: u32, first_time: bool) -> u32 {
        delta /= if first_time { DAMP } else { 2 };
        delta += delta / num_points;
        let mut k = 0;
        while delta > ((BASE - T_MIN) * T_MAX) / 2 {
            delta /= BASE - T_MIN;
            k += BASE;
        }
        k + (((BASE - T_MIN + 1) * delta) / (delta + SKEW))
    }

    let (mut output, rest): (Vec<char>, &str) = match input.rfind('-') {
        None => (Vec::new(), input),
        Some(pos) => (
            input[..pos].chars().collect(),
            if pos > 0 { &input[pos + 1..] } else { input },
        ),
    };
    if output.iter().any(|c| !c.is_ascii()) {
        return None;
    }

    let mut n = INITIAL_N;
    let mut bias = INITIAL_BIAS;
    let mut i: u32 = 0;
    let mut iter = rest.bytes();
    loop {
        let mut weight: u32 = 1;
        let mut k = BASE;
        let mut byte = match iter.next() {
            None => break,
            Some(b) => b,
        };
        let old_i = i;
        loop {
            let digit = match byte {
                b'0'..=b'9' => u32::from(byte - b'0') + 26,
                b'A'..=b'Z' => u32::from(byte - b'A'),
                b'a'..=b'z' => u32::from(byte - b'a'),
                _ => return None,
            };
            i = i.checked_add(digit.checked_mul(weight)?)?;
            let t = if k <= bias {
                T_MIN
            } else if k >= bias + T_MAX {
                T_MAX
            } else {
                k - bias
            };
            if digit < t {
                break;
            }
            weight = weight.checked_mul(BASE - t)?;
            k += BASE;
            byte = match iter.next() {
                None => return None,
                Some(b) => b,
            };
        }
        let length = output.len() as u32 + 1;
        bias = adapt(i - old_i, length, old_i == 0);
        n = n.checked_add(i / length)?;
        i %= length;
        let c = char::from_u32(n)?;
        output.insert(i as usize, c);
        i += 1;
    }
    Some(output.into_iter().collect())
}

/// Error type for a domain name that could not be encoded.
#[derive(Debug, PartialEq)]
pub struct InvalidDomain;

impl Labels {
    pub fn root() -> Self {
        Labels { segments: Vec::new() }
    }

    pub fn segments(&self) -> &[(u8, String)] {
        &self.segments
    }

    /// Parses a user-supplied domain name, applying IDNA processing.
    pub fn encode(input: &str) -> Result<Self, InvalidDomain> {
        // Leniently decode any Punycode labels first, so that non-canonical
        // encodings get re-encoded rather than rejected.
        let mut pre = String::new();
        for (i, label) in input.split('.').enumerate() {
            if i > 0 {
                pre.push('.');
            }
            let lower = label.to_ascii_lowercase();
            if lower.starts_with("xn--") {
                match punycode_decode(&lower[4..]) {
                    Some(decoded) if !decoded.is_empty() => pre.push_str(&decoded),
                    _ => return Err(InvalidDomain),
                }
            } else {
                pre.push_str(label);
            }
        }

        let (unicode, unicode_result) = idna::domain_to_unicode(&pre);
        if unicode_result.is_err() {
            return Err(InvalidDomain);
        }
        for label in unicode.split('.') {
            if label.starts_with('-') || label.ends_with('-') {
                return Err(InvalidDomain);
            }
        }

        let ascii = match idna::domain_to_ascii(&pre) {
            Ok(a) => a,
            Err(_) => return Err(InvalidDomain),
        };

        let mut segments = Vec::new();
        for label in ascii.split('.') {
            if label.is_empty() {
                continue;
            }
            if label.starts_with('-') || label.ends_with('-') {
                return Err(InvalidDomain);
            }
            if label.len() > 63 {
                return Err(InvalidDomain);
            }
            segments.push((label.len() as u8, label.to_string()));
        }
        Ok(Labels { segments })
    }

    /// The number of bytes this name takes up on the wire, uncompressed.
    pub fn wire_len(&self) -> u16 {
        self.segments.iter().map(|(len, _)| u16::from(*len) + 1).sum::<u16>() + 1
    }

    /// Writes this name to the buffer in wire format.
    pub fn write_to(&self, buf: &mut Vec<u8>) {
        for (len, segment) in &self.segments {
            buf.push(*len);
            buf.extend_from_slice(segment.as_bytes());
        }
        buf.push(0);
    }

    /// Reads a name from the cursor, following compression pointers.
    /// Returns the name and the number of bytes consumed at this position.
    pub fn read(c: &mut Cursor<&[u8]>) -> Result<(Labels, u16), WireError> {
        let mut segments = Vec::new();
        let mut recursions = Vec::new();
        let bytes_read = read_labels(c, &mut segments, &mut recursions)?;
        Ok((Labels { segments }, bytes_read))
    }
}

fn read_labels(
    c: &mut Cursor<&[u8]>,
    segments: &mut Vec<(u8, String)>,
    recursions: &mut Vec<u16>,
) -> Result<u16, WireError> {
    let mut bytes_read = 0u16;
    loop {
        let byte = read_u8(c)?;
        if byte == 0 {
            bytes_read += 1;
            return Ok(bytes_read);
        } else if byte & 0b_1100_0000 == 0b_1100_0000 {
            let name_one = byte & !0b_1100_0000;
            let name_two = read_u8(c)?;
            let offset = u16::from_be_bytes([name_one, name_two]);
            bytes_read += 2;

            if recursions.contains(&offset) {
                return Err(WireError::TooMuchRecursion(recursions.clone()));
            }
            recursions.push(offset);

            let new_pos = c.position();
            trace!(TARGET, "Backtracking to offset {}", offset);
            c.set_position(u64::from(offset));
            read_labels(c, segments, recursions)?;
            trace!(TARGET, "Coming back to {}", new_pos);
            c.set_position(new_pos);
            return Ok(bytes_read);
        } else {
            let mut buf = vec![0u8; usize::from(byte)];
            c.read_exact(&mut buf)?;
            let string = String::from_utf8_lossy(&buf).to_string();
            segments.push((byte, string));
            bytes_read += u16::from(byte) + 1;
        }
    }
}
