use super::types::*;

const TARGET: &str = "dns::wire";

/// Things that can go wrong when decoding a packet.
#[derive(PartialEq, Debug)]
pub enum WireError {
    /// Ran out of bytes while reading.
    IO,
    /// A fixed- or minimum-length record had the wrong length.
    WrongRecordLength {
        stated_length: u16,
        mandated_length: MandatedLength,
    },
    /// A record containing a domain name did not take up the stated length.
    WrongLabelLength {
        stated_length: u16,
        length_after_labels: u16,
    },
    /// Compression pointers looped.
    TooMuchRecursion(Vec<u16>),
    /// A record specified a version we do not understand.
    WrongVersion {
        stated_version: u8,
        maximum_supported_version: u8,
    },
}

#[derive(PartialEq, Debug, Clone, Copy)]
pub enum MandatedLength {
    Exactly(u16),
    AtLeast(u16),
}

impl From<io::Error> for WireError {
    fn from(ioe: io::Error) -> Self {
        error!(TARGET, "IO error -> {:?}", ioe);
        WireError::IO
    }
}

impl fmt::Display for WireError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            WireError::IO => write!(f, "Malformed packet: insufficient data"),
            WireError::WrongRecordLength {
                stated_length,
                mandated_length: MandatedLength::Exactly(n),
            } => write!(
                f,
                "Malformed packet: record length should be {}, got {}",
                n, stated_length
            ),
            WireError::WrongRecordLength {
                stated_length,
                mandated_length: MandatedLength::AtLeast(n),
            } => write!(
                f,
                "Malformed packet: record length should be at least {}, got {}",
                n, stated_length
            ),
            WireError::WrongLabelLength {
                stated_length,
                length_after_labels,
            } => write!(
                f,
                "Malformed packet: length {} was specified, but read {} bytes",
                stated_length, length_after_labels
            ),
            WireError::TooMuchRecursion(list) => {
                write!(f, "Malformed packet: too much recursion: {:?}", list)
            }
            WireError::WrongVersion {
                stated_version,
                maximum_supported_version,
            } => write!(
                f,
                "Malformed packet: record specifies version {}, expected up to {}",
                stated_version, maximum_supported_version
            ),
        }
    }
}

pub fn read_u8(c: &mut Cursor<&[u8]>) -> io::Result<u8> {
    let mut buf = [0u8; 1];
    c.read_exact(&mut buf)?;
    Ok(buf[0])
}

pub fn read_u16(c: &mut Cursor<&[u8]>) -> io::Result<u16> {
    let mut buf = [0u8; 2];
    c.read_exact(&mut buf)?;
    Ok(u16::from_be_bytes(buf))
}

pub fn read_u32(c: &mut Cursor<&[u8]>) -> io::Result<u32> {
    let mut buf = [0u8; 4];
    c.read_exact(&mut buf)?;
    Ok(u32::from_be_bytes(buf))
}

impl Request {
    /// Converts this request to bytes ready to be sent.
    pub fn to_bytes(&self) -> Vec<u8> {
        let mut bytes = Vec::with_capacity(64);
        bytes.extend_from_slice(&self.transaction_id.to_be_bytes());
        bytes.extend_from_slice(&self.flags.to_u16().to_be_bytes());
        bytes.extend_from_slice(&1u16.to_be_bytes()); // query count
        bytes.extend_from_slice(&0u16.to_be_bytes()); // answer count
        bytes.extend_from_slice(&0u16.to_be_bytes()); // authority count
        let additional_count: u16 = if self.additional.is_some() { 1 } else { 0 };
        bytes.extend_from_slice(&additional_count.to_be_bytes());

        self.query.qname.write_to(&mut bytes);
        bytes.extend_from_slice(&self.query.qtype.number().to_be_bytes());
        bytes.extend_from_slice(&self.query.qclass.number().to_be_bytes());

        if let Some(opt) = &self.additional {
            bytes.push(0); // root name
            bytes.extend_from_slice(&RecordType::OPT.number().to_be_bytes());
            bytes.extend_from_slice(&opt.udp_payload_size.to_be_bytes());
            bytes.push(opt.higher_bits);
            bytes.push(opt.edns0_version);
            bytes.extend_from_slice(&opt.flags.to_be_bytes());
            bytes.extend_from_slice(&(opt.data.len() as u16).to_be_bytes());
            bytes.extend_from_slice(&opt.data);
        }
        bytes
    }
}

impl Response {
    /// Parses a response from the given bytes.
    pub fn from_bytes(bytes: &[u8]) -> Result<Response, WireError> {
        info!(TARGET, "Parsing response");
        trace!(TARGET, "Bytes -> {:?}", bytes);

        let mut c = Cursor::new(bytes);
        let transaction_id = read_u16(&mut c)?;
        trace!(TARGET, "Read txid -> {:?}", transaction_id);

        let flags = Flags::from_u16(read_u16(&mut c)?);
        trace!(TARGET, "Read flags -> {:#?}", flags);

        let query_count = read_u16(&mut c)?;
        let answer_count = read_u16(&mut c)?;
        let authority_count = read_u16(&mut c)?;
        let additional_count = read_u16(&mut c)?;

        let mut queries = Vec::new();
        debug!(TARGET, "Reading {}x query from response", query_count);
        for _ in 0..query_count {
            let (qname, _) = Labels::read(&mut c)?;
            queries.push(read_query(qname, &mut c)?);
        }

        let mut answers = Vec::new();
        debug!(TARGET, "Reading {}x answer from response", answer_count);
        for _ in 0..answer_count {
            let (qname, _) = Labels::read(&mut c)?;
            answers.push(read_answer(qname, &mut c)?);
        }

        let mut authorities = Vec::new();
        debug!(TARGET, "Reading {}x authority from response", authority_count);
        for _ in 0..authority_count {
            let (qname, _) = Labels::read(&mut c)?;
            authorities.push(read_answer(qname, &mut c)?);
        }

        let mut additionals = Vec::new();
        debug!(TARGET, "Reading {}x additional answer from response", additional_count);
        for _ in 0..additional_count {
            let (qname, _) = Labels::read(&mut c)?;
            additionals.push(read_answer(qname, &mut c)?);
        }

        Ok(Response {
            transaction_id,
            flags,
            queries,
            answers,
            authorities,
            additionals,
        })
    }
}

fn read_query(qname: Labels, c: &mut Cursor<&[u8]>) -> Result<Query, WireError> {
    let qtype_number = read_u16(c)?;
    trace!(TARGET, "Read qtype number -> {:?}", qtype_number);
    let qtype = RecordType::from_number(qtype_number);
    trace!(TARGET, "Found qtype -> {:?}", qtype);

    let qclass = QClass::from_number(read_u16(c)?);
    trace!(TARGET, "Read qclass -> {:?}", qtype);

    Ok(Query { qname, qclass, qtype })
}

fn read_answer(qname: Labels, c: &mut Cursor<&[u8]>) -> Result<Section, WireError> {
    let qtype_number = read_u16(c)?;
    trace!(TARGET, "Read qtype number -> {:?}", qtype_number);

    if qtype_number == RecordType::OPT.number() {
        let opt = Record::read_opt(c)?;
        return Ok(Section::Pseudo(qname, opt));
    }

    let qtype = RecordType::from_number(qtype_number);
    trace!(TARGET, "Found qtype -> {:?}", qtype);

    let qclass = QClass::from_number(read_u16(c)?);
    trace!(TARGET, "Read qclass -> {:?}", qtype);

    let ttl = read_u32(c)?;
    trace!(TARGET, "Read TTL -> {:?}", ttl);

    let record_length = read_u16(c)?;
    trace!(TARGET, "Read record length -> {:?}", record_length);

    let record = Record::read(qtype, record_length, c)?;
    Ok(Section::Standard(Answer {
        qname,
        qclass,
        ttl,
        record,
    }))
}
EOF
echo done"}

