//! The individual record types, their wire-format parsers, and their
//! human-readable and JSON representations.

use std::fmt::Write as _;
use std::io::{Cursor, Read};
use std::net::{Ipv4Addr, Ipv6Addr};

use super::strings::Labels;
use super::types::{OptRecord, RecordType, UnknownQtype};
use super::wire::{read_u16, read_u32, read_u8, MandatedLength, WireError};
use crate::json::{self, JsonObject};

/// A position on the Earth, for LOC records.
#[derive(PartialEq, Debug, Clone, Copy)]
pub struct Position {
    pub degrees: u32,
    pub arcminutes: u32,
    pub arcseconds: u32,
    pub milliarcseconds: u32,
    pub direction: Direction,
}

#[derive(PartialEq, Debug, Clone, Copy)]
pub enum Direction {
    North,
    East,
    South,
    West,
}

impl Position {
    fn from_u32(input: u32, vertical: bool) -> Option<Self> {
        let (gap, direction) = if input >= 0x8000_0000 {
            (input - 0x8000_0000, if vertical { Direction::North } else { Direction::East })
        } else {
            (0x8000_0000 - input, if vertical { Direction::South } else { Direction::West })
        };
        let limit = if vertical { 90 } else { 180 };
        if gap > limit * 3_600_000 {
            return None;
        }
        let milliarcseconds = gap % 1000;
        let total_arcseconds = gap / 1000;
        let arcseconds = total_arcseconds % 60;
        let total_arcminutes = total_arcseconds / 60;
        let arcminutes = total_arcminutes % 60;
        let degrees = total_arcminutes / 60;
        Some(Position {
            degrees,
            arcminutes,
            arcseconds,
            milliarcseconds,
            direction,
        })
    }

    pub fn to_string(&self) -> String {
        let dir = match self.direction {
            Direction::North => "N",
            Direction::East => "E",
            Direction::South => "S",
            Direction::West => "W",
        };
        if self.milliarcseconds == 0 {
            format!(
                "{}°{}′{}″ {}",
                self.degrees, self.arcminutes, self.arcseconds, dir
            )
        } else {
            format!(
                "{}°{}′{}.{:03}″ {}",
                self.degrees, self.arcminutes, self.arcseconds, self.milliarcseconds, dir
            )
        }
    }
}

/// An altitude in centimetres relative to the LOC base.
#[derive(PartialEq, Debug, Clone, Copy)]
pub struct Altitude {
    centimetres: i64,
}

impl Altitude {
    fn from_u32(input: u32) -> Self {
        Altitude {
            centimetres: i64::from(input) - 10_000_000,
        }
    }

    pub fn to_string(&self) -> String {
        let metres = self.centimetres / 100;
        let rem = self.centimetres % 100;
        if rem == 0 {
            format!("{}m", metres)
        } else {
            format!("{}.{:02}m", metres, rem)
        }
    }
}

#[derive(PartialEq, Debug, Clone)]
#[allow(clippy::upper_case_acronyms)]
pub enum Record {
    A {
        address: Ipv4Addr,
    },
    AAAA {
        address: Ipv6Addr,
    },
    CAA {
        critical: bool,
        tag: Vec<u8>,
        value: Vec<u8>,
    },
    CNAME {
        domain: Labels,
    },
    EUI48 {
        octets: [u8; 6],
    },
    EUI64 {
        octets: [u8; 8],
    },
    HINFO {
        cpu: Vec<u8>,
        os: Vec<u8>,
    },
    LOC {
        size: u8,
        horizontal_precision: u8,
        vertical_precision: u8,
        latitude: Option<Position>,
        longitude: Option<Position>,
        altitude: Altitude,
    },
    MX {
        preference: u16,
        exchange: Labels,
    },
    NAPTR {
        order: u16,
        preference: u16,
        flags: Vec<u8>,
        service: Vec<u8>,
        regex: Vec<u8>,
        replacement: Labels,
    },
    NS {
        nameserver: Labels,
    },
    OPENPGPKEY {
        key: Vec<u8>,
    },
    PTR {
        cname: Labels,
    },
    SOA {
        mname: Labels,
        rname: Labels,
        serial: u32,
        refresh_interval: u32,
        retry_interval: u32,
        expire_limit: u32,
        minimum_ttl: u32,
    },
    SRV {
        priority: u16,
        weight: u16,
        port: u16,
        target: Labels,
    },
    SSHFP {
        algorithm: u8,
        fingerprint_type: u8,
        fingerprint: Vec<u8>,
    },
    TLSA {
        certificate_usage: u8,
        selector: u8,
        matching_type: u8,
        certificate_data: Vec<u8>,
    },
    TXT {
        messages: Vec<Vec<u8>>,
    },
    URI {
        priority: u16,
        weight: u16,
        target: Vec<u8>,
    },
    Other {
        type_number: UnknownQtype,
        bytes: Vec<u8>,
    },
}

/// Reads exactly `len` bytes from the cursor.
fn read_bytes(c: &mut Cursor<&[u8]>, len: usize) -> Result<Vec<u8>, WireError> {
    let mut buf = vec![0u8; len];
    c.read_exact(&mut buf)?;
    Ok(buf)
}

fn lossy(bytes: &[u8]) -> String {
    String::from_utf8_lossy(bytes).to_string()
}

/// Formats a size nibble-pair as it appears in LOC records (`1e2`).
pub fn loc_size_string(size: u8) -> String {
    format!("{}e{}", size >> 4, size & 0x0F)
}

impl Record {
    /// Reads a record of the given type from the cursor.
    pub fn read(
        qtype: RecordType,
        stated_length: u16,
        c: &mut Cursor<&[u8]>,
    ) -> Result<Record, WireError> {
        macro_rules! info_parsing {
            ($name:expr) => {
                info!(
                    "dns::wire",
                    "Parsing {} record (type {}, len {})",
                    $name,
                    qtype.number(),
                    stated_length
                );
            };
        }

        match qtype {
            RecordType::A => {
                info_parsing!("A");
                Self::read_a(stated_length, c)
            }
            RecordType::AAAA => {
                info_parsing!("AAAA");
                Self::read_aaaa(stated_length, c)
            }
            RecordType::CAA => {
                info_parsing!("CAA");
                Self::read_caa(stated_length, c)
            }
            RecordType::CNAME => {
                info_parsing!("CNAME");
                Self::read_cname(stated_length, c)
            }
            RecordType::EUI48 => {
                info_parsing!("EUI48");
                Self::read_eui48(stated_length, c)
            }
            RecordType::EUI64 => {
                info_parsing!("EUI64");
                Self::read_eui64(stated_length, c)
            }
            RecordType::HINFO => {
                info_parsing!("HINFO");
                Self::read_hinfo(stated_length, c)
            }
            RecordType::LOC => {
                info_parsing!("LOC");
                Self::read_loc(stated_length, c)
            }
            RecordType::MX => {
                info_parsing!("MX");
                Self::read_mx(stated_length, c)
            }
            RecordType::NAPTR => {
                info_parsing!("NAPTR");
                Self::read_naptr(stated_length, c)
            }
            RecordType::NS => {
                info_parsing!("NS");
                Self::read_ns(stated_length, c)
            }
            RecordType::OPENPGPKEY => {
                info_parsing!("OPENPGPKEY");
                Self::read_openpgpkey(stated_length, c)
            }
            RecordType::PTR => {
                info_parsing!("PTR");
                Self::read_ptr(stated_length, c)
            }
            RecordType::SOA => {
                info_parsing!("SOA");
                Self::read_soa(stated_length, c)
            }
            RecordType::SRV => {
                info_parsing!("SRV");
                Self::read_srv(stated_length, c)
            }
            RecordType::SSHFP => {
                info_parsing!("SSHFP");
                Self::read_sshfp(stated_length, c)
            }
            RecordType::TLSA => {
                info_parsing!("TLSA");
                Self::read_tlsa(stated_length, c)
            }
            RecordType::TXT => {
                info_parsing!("TXT");
                Self::read_txt(stated_length, c)
            }
            RecordType::URI => {
                info_parsing!("URI");
                Self::read_uri(stated_length, c)
            }
            RecordType::OPT => {
                // OPT records are handled before we get here, but if one
                // arrives through this path, treat its bytes as opaque.
                let bytes = read_bytes(c, usize::from(stated_length))?;
                Ok(Record::Other {
                    type_number: UnknownQtype::UnheardOf(41),
                    bytes,
                })
            }
            RecordType::Other(type_number) => {
                let bytes = read_bytes(c, usize::from(stated_length))?;
                Ok(Record::Other { type_number, bytes })
            }
        }
    }

    /// Reads an OPT pseudo-record, starting after the type number.
    pub fn read_opt(c: &mut Cursor<&[u8]>) -> Result<OptRecord, WireError> {
        const T: &str = "dns::record::opt";
        let udp_payload_size = read_u16(c)?;
        trace!(T, "Parsed UDP payload size -> {:?}", udp_payload_size);

        let higher_bits = read_u8(c)?;
        trace!(T, "Parsed higher bits -> {:#08b}", higher_bits);

        let edns0_version = read_u8(c)?;
        trace!(T, "Parsed EDNS(0) version -> {:?}", edns0_version);

        let flags = read_u16(c)?;
        trace!(T, "Parsed flags -> {:#08b}", flags);

        let data_length = read_u16(c)?;
        trace!(T, "Parsed data length -> {:?}", data_length);

        let data = read_bytes(c, usize::from(data_length))?;
        trace!(T, "Parsed data -> {:?}", data);

        Ok(OptRecord {
            udp_payload_size,
            higher_bits,
            edns0_version,
            flags,
            data,
        })
    }

    fn read_a(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::a";
        if stated_length != 4 {
            warn!(T, "Length is incorrect (record length {}, but should be four)", stated_length);
            return Err(WireError::WrongRecordLength {
                stated_length,
                mandated_length: MandatedLength::Exactly(4),
            });
        }
        let mut buf = [0u8; 4];
        c.read_exact(&mut buf)?;
        let address = Ipv4Addr::from(buf);
        trace!(T, "Parsed IPv4 address -> {}", address);
        Ok(Record::A { address })
    }

    fn read_aaaa(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::aaaa";
        if stated_length != 16 {
            warn!(T, "Length is incorrect (stated length {}, but should be sixteen)", stated_length);
            return Err(WireError::WrongRecordLength {
                stated_length,
                mandated_length: MandatedLength::Exactly(16),
            });
        }
        let mut buf = [0u8; 16];
        c.read_exact(&mut buf)?;
        let address = Ipv6Addr::from(buf);
        trace!(T, "Parsed IPv6 address -> {}", address);
        Ok(Record::AAAA { address })
    }

    fn read_caa(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::caa";
        let flags = read_u8(c)?;
        trace!(T, "Parsed flags -> {:#08b}", flags);

        let critical = flags & 0b_1000_0000 == 0b_1000_0000;
        trace!(T, "Parsed critical flag -> {:?}", critical);

        let tag_length = read_u8(c)?;
        trace!(T, "Parsed tag length -> {:?}", tag_length);

        let tag = read_bytes(c, usize::from(tag_length))?;
        trace!(T, "Parsed tag -> {:?}", lossy(&tag));

        let remaining_length = stated_length
            .saturating_sub(u16::from(tag_length))
            .saturating_sub(2);
        trace!(T, "Remaining length -> {:?}", remaining_length);

        let value = read_bytes(c, usize::from(remaining_length))?;
        trace!(T, "Parsed value -> {:?}", lossy(&value));

        Ok(Record::CAA {
            critical,
            tag,
            value,
        })
    }

    fn read_cname(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::cname";
        let (domain, domain_length) = Labels::read(c)?;
        trace!(T, "Parsed domain -> {:?}", domain);

        if stated_length == domain_length {
            trace!(T, "Length is correct");
            Ok(Record::CNAME { domain })
        } else {
            warn!(T, "Length is incorrect (stated length {}, domain length {})", stated_length, domain_length);
            Err(WireError::WrongLabelLength {
                stated_length,
                length_after_labels: domain_length,
            })
        }
    }

