    fn read_hinfo(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::hinfo";
        let cpu_length = read_u8(c)?;
        trace!(T, "Parsed CPU length -> {:?}", cpu_length);
        let cpu = read_bytes(c, usize::from(cpu_length))?;
        trace!(T, "Parsed CPU -> {:?}", lossy(&cpu));

        let os_length = read_u8(c)?;
        trace!(T, "Parsed OS length -> {:?}", os_length);
        let os = read_bytes(c, usize::from(os_length))?;
        trace!(T, "Parsed OS -> {:?}", lossy(&os));

        let length_after_labels = 1 + u16::from(cpu_length) + 1 + u16::from(os_length);
        if stated_length == length_after_labels {
            trace!(T, "Length is correct");
            Ok(Record::HINFO { cpu, os })
        } else {
            warn!(T, "Length is incorrect (stated length {}, cpu plus length {}", stated_length, length_after_labels);
            Err(WireError::WrongLabelLength {
                stated_length,
                length_after_labels,
            })
        }
    }

    fn read_loc(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::loc";
        let version = read_u8(c)?;
        trace!(T, "Parsed version -> {:?}", version);

        if version != 0 {
            return Err(WireError::WrongVersion {
                stated_version: version,
                maximum_supported_version: 0,
            });
        }

        if stated_length != 16 {
            return Err(WireError::WrongRecordLength {
                stated_length,
                mandated_length: MandatedLength::Exactly(16),
            });
        }

        let size = read_u8(c)?;
        trace!(T, "Parsed size -> {:#08b} ({})", size, loc_size_string(size));

        let horizontal_precision = read_u8(c)?;
        trace!(T, "Parsed horizontal precision -> {:?}", horizontal_precision);

        let vertical_precision = read_u8(c)?;
        trace!(T, "Parsed vertical precision -> {:?}", vertical_precision);

        let latitude_num = read_u32(c)?;
        let latitude = Position::from_u32(latitude_num, true);
        trace!(T, "Parsed latitude -> {:?} ({:?})", latitude_num, latitude);

        let longitude_num = read_u32(c)?;
        let longitude = Position::from_u32(longitude_num, false);
        trace!(T, "Parsed longitude -> {:?} ({:?})", longitude_num, longitude);

        let altitude_num = read_u32(c)?;
        let altitude = Altitude::from_u32(altitude_num);
        trace!(T, "Parsed altitude -> {:?} ({})", altitude_num, altitude.to_string());

        Ok(Record::LOC {
            size,
            horizontal_precision,
            vertical_precision,
            latitude,
            longitude,
            altitude,
        })
    }

    fn read_mx(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::mx";
