        trace!(T, "Parsed preference -> {:?}", preference);

        let (exchange, exchange_length) = Labels::read(c)?;
        trace!(T, "Parsed exchange -> {:?}", exchange);

        let length_after_labels = 2 + exchange_length;
        if stated_length == length_after_labels {
            trace!(T, "Length is correct");
            Ok(Record::MX { preference, exchange })
        } else {
            warn!(T, "Length is incorrect (stated length {}, preference plus exchange length {}", stated_length, length_after_labels);
            Err(WireError::WrongLabelLength {
                stated_length,
                length_after_labels,
            })
        }
    }

    fn read_naptr(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::naptr";
        let order = read_u16(c)?;
        trace!(T, "Parsed order -> {:?}", order);

        let preference = read_u16(c)?;
        trace!(T, "Parsed preference -> {:?}", preference);

        let flags_length = read_u8(c)?;
        trace!(T, "Parsed flags length -> {:?}", flags_length);
        let flags = read_bytes(c, usize::from(flags_length))?;
        trace!(T, "Parsed flags -> {:?}", lossy(&flags));

        let service_length = read_u8(c)?;
        trace!(T, "Parsed service length -> {:?}", service_length);
        let service = read_bytes(c, usize::from(service_length))?;
        trace!(T, "Parsed service -> {:?}", lossy(&service));

        let regex_length = read_u8(c)?;
        trace!(T, "Parsed regex length -> {:?}", regex_length);
        let regex = read_bytes(c, usize::from(regex_length))?;
        trace!(T, "Parsed regex -> {:?}", lossy(&regex));

        let (replacement, replacement_length) = Labels::read(c)?;
        trace!(T, "Parsed replacement -> {:?}", replacement);

        let length_after_labels = 2
            + 2
            + 1
            + u16::from(flags_length)
            + 1
            + u16::from(service_length)
            + 1
            + u16::from(regex_length)
            + replacement_length;
        if stated_length == length_after_labels {
            Ok(Record::NAPTR {
                order,
                preference,
                flags,
                service,
                regex,
                replacement,
            })
        } else {
            Err(WireError::WrongLabelLength {
                stated_length,
                length_after_labels,
            })
        }
    }

