//! The individual record types, their wire-format parsers, and their
//! human-readable and JSON representations.

use std::fmt::Write as _;
use std::io::{Cursor, Read};
use std::net::{Ipv4Addr, Ipv6Addr};

use super::strings::Labels;
use super::types::{OptRecord, RecordType, UnknownQtype};
use super::wire::{read_u16, read_u32, read_u8, MandatedLength, WireError};
use crate::json::{self, JsonObject};

/// A position on the Earth, for LOC records.
#[derive(PartialEq, Debug, Clone, Copy)]
pub struct Position {
    pub degrees: u32,
    pub arcminutes: u32,
    pub arcseconds: u32,
    pub milliarcseconds: u32,
    pub direction: Direction,
}

#[derive(PartialEq, Debug, Clone, Copy)]
pub enum Direction {
    North,
    East,
    South,
    West,
}

impl Position {
    fn from_u32(input: u32, vertical: bool) -> Option<Self> {
        let (gap, direction) = if input >= 0x8000_0000 {
            (input - 0x8000_0000, if vertical { Direction::North } else { Direction::East })
        } else {
            (0x8000_0000 - input, if vertical { Direction::South } else { Direction::West })
        };
        let limit = if vertical { 90 } else { 180 };
        if gap > limit * 3_600_000 {
            return None;
        }
        let milliarcseconds = gap % 1000;
        let total_arcseconds = gap / 1000;
        let arcseconds = total_arcseconds % 60;
        let total_arcminutes = total_arcseconds / 60;
        let arcminutes = total_arcminutes % 60;
        let degrees = total_arcminutes / 60;
        Some(Position {
            degrees,
            arcminutes,
            arcseconds,
            milliarcseconds,
            direction,
        })
    }

    pub fn to_string(&self) -> String {
        let dir = match self.direction {
            Direction::North => "N",
            Direction::East => "E",
            Direction::South => "S",
            Direction::West => "W",
        };
        if self.milliarcseconds == 0 {
            format!(
                "{}°{}′{}″ {}",
                self.degrees, self.arcminutes, self.arcseconds, dir
            )
        } else {
            format!(
                "{}°{}′{}.{:03}″ {}",
                self.degrees, self.arcminutes, self.arcseconds, self.milliarcseconds, dir
            )
        }
    }
}

/// An altitude in centimetres relative to the LOC base.
#[derive(PartialEq, Debug, Clone, Copy)]
pub struct Altitude {
    centimetres: i64,
}

impl Altitude {
    fn from_u32(input: u32) -> Self {
        Altitude {
            centimetres: i64::from(input) - 10_000_000,
        }
    }

    pub fn to_string(&self) -> String {
        let metres = self.centimetres / 100;
        let rem = self.centimetres % 100;
        if rem == 0 {
            format!("{}m", metres)
        } else {
            format!("{}.{:02}m", metres, rem)
        }
    }
}

#[derive(PartialEq, Debug, Clone)]
#[allow(clippy::upper_case_acronyms)]
pub enum Record {
    A {
        address: Ipv4Addr,
    },
    AAAA {
        address: Ipv6Addr,
    },
    CAA {
        critical: bool,
        tag: Vec<u8>,
        value: Vec<u8>,
    },
    CNAME {
        domain: Labels,
    },
    EUI48 {
        octets: [u8; 6],
    },
    EUI64 {
        octets: [u8; 8],
    },
    HINFO {
        cpu: Vec<u8>,
        os: Vec<u8>,
    },
    LOC {
        size: u8,
        horizontal_precision: u8,
        vertical_precision: u8,
        latitude: Option<Position>,
        longitude: Option<Position>,
        altitude: Altitude,
    },
    MX {
        preference: u16,
        exchange: Labels,
    },
    NAPTR {
        order: u16,
        preference: u16,
        flags: Vec<u8>,
        service: Vec<u8>,
        regex: Vec<u8>,
        replacement: Labels,
    },
    NS {
        nameserver: Labels,
    },
    OPENPGPKEY {
        key: Vec<u8>,
    },
    PTR {
        cname: Labels,
    },
    SOA {
        mname: Labels,
        rname: Labels,
        serial: u32,
        refresh_interval: u32,
        retry_interval: u32,
        expire_limit: u32,
        minimum_ttl: u32,
    },
    SRV {
        priority: u16,
        weight: u16,
        port: u16,
        target: Labels,
    },
    SSHFP {
        algorithm: u8,
        fingerprint_type: u8,
        fingerprint: Vec<u8>,
    },
    TLSA {
        certificate_usage: u8,
        selector: u8,
        matching_type: u8,
        certificate_data: Vec<u8>,
    },
    TXT {
        messages: Vec<Vec<u8>>,
    },
    URI {
        priority: u16,
        weight: u16,
        target: Vec<u8>,
    },
    Other {
        type_number: UnknownQtype,
        bytes: Vec<u8>,
    },
}

/// Reads exactly `len` bytes from the cursor.
fn read_bytes(c: &mut Cursor<&[u8]>, len: usize) -> Result<Vec<u8>, WireError> {
    let mut buf = vec![0u8; len];
    c.read_exact(&mut buf)?;
    Ok(buf)
}

fn lossy(bytes: &[u8]) -> String {
    String::from_utf8_lossy(bytes).to_string()
}

/// Formats a size nibble-pair as it appears in LOC records (`1e2`).
pub fn loc_size_string(size: u8) -> String {
    format!("{}e{}", size >> 4, size & 0x0F)
}

impl Record {
    /// Reads a record of the given type from the cursor.
    pub fn read(
        qtype: RecordType,
        stated_length: u16,
        c: &mut Cursor<&[u8]>,
    ) -> Result<Record, WireError> {
        macro_rules! info_parsing {
            ($name:expr) => {
                info!(
                    "dns::wire",
                    "Parsing {} record (type {}, len {})",
                    $name,
                    qtype.number(),
                    stated_length
                );
            };
        }

        match qtype {
            RecordType::A => {
                info_parsing!("A");
                Self::read_a(stated_length, c)
            }
            RecordType::AAAA => {
                info_parsing!("AAAA");
                Self::read_aaaa(stated_length, c)
            }
            RecordType::CAA => {
                info_parsing!("CAA");
                Self::read_caa(stated_length, c)
            }
            RecordType::CNAME => {
                info_parsing!("CNAME");
                Self::read_cname(stated_length, c)
            }
            RecordType::EUI48 => {
                info_parsing!("EUI48");
                Self::read_eui48(stated_length, c)
            }
            RecordType::EUI64 => {
                info_parsing!("EUI64");
                Self::read_eui64(stated_length, c)
            }
            RecordType::HINFO => {
                info_parsing!("HINFO");
                Self::read_hinfo(stated_length, c)
            }
            RecordType::LOC => {
                info_parsing!("LOC");
                Self::read_loc(stated_length, c)
            }
            RecordType::MX => {
                info_parsing!("MX");
                Self::read_mx(stated_length, c)
            }
            RecordType::NAPTR => {
                info_parsing!("NAPTR");
                Self::read_naptr(stated_length, c)
            }
            RecordType::NS => {
                info_parsing!("NS");
                Self::read_ns(stated_length, c)
            }
            RecordType::OPENPGPKEY => {
                info_parsing!("OPENPGPKEY");
                Self::read_openpgpkey(stated_length, c)
            }
            RecordType::PTR => {
                info_parsing!("PTR");
                Self::read_ptr(stated_length, c)
            }
            RecordType::SOA => {
                info_parsing!("SOA");
                Self::read_soa(stated_length, c)
            }
            RecordType::SRV => {
                info_parsing!("SRV");
                Self::read_srv(stated_length, c)
            }
            RecordType::SSHFP => {
                info_parsing!("SSHFP");
                Self::read_sshfp(stated_length, c)
            }
            RecordType::TLSA => {
                info_parsing!("TLSA");
                Self::read_tlsa(stated_length, c)
            }
            RecordType::TXT => {
                info_parsing!("TXT");
                Self::read_txt(stated_length, c)
            }
            RecordType::URI => {
                info_parsing!("URI");
                Self::read_uri(stated_length, c)
            }
            RecordType::OPT => {
                // OPT records are handled before we get here, but if one
                // arrives through this path, treat its bytes as opaque.
                let bytes = read_bytes(c, usize::from(stated_length))?;
                Ok(Record::Other {
                    type_number: UnknownQtype::UnheardOf(41),
                    bytes,
                })
            }
            RecordType::Other(type_number) => {
                let bytes = read_bytes(c, usize::from(stated_length))?;
                Ok(Record::Other { type_number, bytes })
            }
        }
    }

    /// Reads an OPT pseudo-record, starting after the type number.
    pub fn read_opt(c: &mut Cursor<&[u8]>) -> Result<OptRecord, WireError> {
        const T: &str = "dns::record::opt";
        let udp_payload_size = read_u16(c)?;
        trace!(T, "Parsed UDP payload size -> {:?}", udp_payload_size);

        let higher_bits = read_u8(c)?;
        trace!(T, "Parsed higher bits -> {:#08b}", higher_bits);

        let edns0_version = read_u8(c)?;
        trace!(T, "Parsed EDNS(0) version -> {:?}", edns0_version);

        let flags = read_u16(c)?;
        trace!(T, "Parsed flags -> {:#08b}", flags);

        let data_length = read_u16(c)?;
        trace!(T, "Parsed data length -> {:?}", data_length);

        let data = read_bytes(c, usize::from(data_length))?;
        trace!(T, "Parsed data -> {:?}", data);

        Ok(OptRecord {
            udp_payload_size,
            higher_bits,
            edns0_version,
            flags,
            data,
        })
    }

    fn read_a(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::a";
        if stated_length != 4 {
            warn!(T, "Length is incorrect (record length {}, but should be four)", stated_length);
            return Err(WireError::WrongRecordLength {
                stated_length,
                mandated_length: MandatedLength::Exactly(4),
            });
        }
        let mut buf = [0u8; 4];
        c.read_exact(&mut buf)?;
        let address = Ipv4Addr::from(buf);
        trace!(T, "Parsed IPv4 address -> {}", address);
        Ok(Record::A { address })
    }

    fn read_aaaa(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::aaaa";
        if stated_length != 16 {
            warn!(T, "Length is incorrect (stated length {}, but should be sixteen)", stated_length);
            return Err(WireError::WrongRecordLength {
                stated_length,
                mandated_length: MandatedLength::Exactly(16),
            });
        }
        let mut buf = [0u8; 16];
        c.read_exact(&mut buf)?;
        let address = Ipv6Addr::from(buf);
        trace!(T, "Parsed IPv6 address -> {}", address);
        Ok(Record::AAAA { address })
    }

    fn read_caa(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::caa";
        let flags = read_u8(c)?;
        trace!(T, "Parsed flags -> {:#08b}", flags);

        let critical = flags & 0b_1000_0000 == 0b_1000_0000;
        trace!(T, "Parsed critical flag -> {:?}", critical);

        let tag_length = read_u8(c)?;
        trace!(T, "Parsed tag length -> {:?}", tag_length);

        let tag = read_bytes(c, usize::from(tag_length))?;
        trace!(T, "Parsed tag -> {:?}", lossy(&tag));

        let remaining_length = stated_length
            .saturating_sub(u16::from(tag_length))
            .saturating_sub(2);
        trace!(T, "Remaining length -> {:?}", remaining_length);

        let value = read_bytes(c, usize::from(remaining_length))?;
        trace!(T, "Parsed value -> {:?}", lossy(&value));

        Ok(Record::CAA {
            critical,
            tag,
            value,
        })
    }

    fn read_cname(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::cname";
        let (domain, domain_length) = Labels::read(c)?;
        trace!(T, "Parsed domain -> {:?}", domain);

        if stated_length == domain_length {
            trace!(T, "Length is correct");
            Ok(Record::CNAME { domain })
        } else {
            warn!(T, "Length is incorrect (stated length {}, domain length {})", stated_length, domain_length);
            Err(WireError::WrongLabelLength {
                stated_length,
                length_after_labels: domain_length,
            })
        }
    }

    fn read_eui48(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::eui48";
        if stated_length != 6 {
            warn!(T, "Length is incorrect (record length {}, but should be six)", stated_length);
            return Err(WireError::WrongRecordLength {
                stated_length,
                mandated_length: MandatedLength::Exactly(6),
            });
        }
        let mut octets = [0u8; 6];
        c.read_exact(&mut octets)?;
        trace!(T, "Parsed 6-byte address -> [\n]");
        Ok(Record::EUI48 { octets })
    }

    fn read_eui64(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::eui64";
        if stated_length != 8 {
            warn!(T, "Length is incorrect (record length {}, but should be eight)", stated_length);
            return Err(WireError::WrongRecordLength {
                stated_length,
                mandated_length: MandatedLength::Exactly(8),
            });
        }
        let mut octets = [0u8; 8];
        c.read_exact(&mut octets)?;
        trace!(T, "Parsed 8-byte address -> [\n]");
        Ok(Record::EUI64 { octets })
    }

    fn read_hinfo(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::hinfo";
        let cpu_length = read_u8(c)?;
        trace!(T, "Parsed CPU length -> {:?}", cpu_length);
        let cpu = read_bytes(c, usize::from(cpu_length))?;
        trace!(T, "Parsed CPU -> {:?}", lossy(&cpu));

        let os_length = read_u8(c)?;
        trace!(T, "Parsed OS length -> {:?}", os_length);
        let os = read_bytes(c, usize::from(os_length))?;
        trace!(T, "Parsed OS -> {:?}", lossy(&os));

        let length_after_labels = 1 + u16::from(cpu_length) + 1 + u16::from(os_length);
        if stated_length == length_after_labels {
            trace!(T, "Length is correct");
            Ok(Record::HINFO { cpu, os })
        } else {
            warn!(T, "Length is incorrect (stated length {}, cpu plus length {}", stated_length, length_after_labels);
            Err(WireError::WrongLabelLength {
                stated_length,
                length_after_labels,
            })
        }
    }

    fn read_loc(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::loc";
        let version = read_u8(c)?;
        trace!(T, "Parsed version -> {:?}", version);

        if version != 0 {
            return Err(WireError::WrongVersion {
                stated_version: version,
                maximum_supported_version: 0,
            });
        }

        if stated_length != 16 {
            return Err(WireError::WrongRecordLength {
                stated_length,
                mandated_length: MandatedLength::Exactly(16),
            });
        }

        let size = read_u8(c)?;
        trace!(T, "Parsed size -> {:#08b} ({})", size, loc_size_string(size));

        let horizontal_precision = read_u8(c)?;
        trace!(T, "Parsed horizontal precision -> {:?}", horizontal_precision);

        let vertical_precision = read_u8(c)?;
        trace!(T, "Parsed vertical precision -> {:?}", vertical_precision);

        let latitude_num = read_u32(c)?;
        let latitude = Position::from_u32(latitude_num, true);
        trace!(T, "Parsed latitude -> {:?} ({:?})", latitude_num, latitude);

        let longitude_num = read_u32(c)?;
        let longitude = Position::from_u32(longitude_num, false);
        trace!(T, "Parsed longitude -> {:?} ({:?})", longitude_num, longitude);

        let altitude_num = read_u32(c)?;
        let altitude = Altitude::from_u32(altitude_num);
        trace!(T, "Parsed altitude -> {:?} ({})", altitude_num, altitude.to_string());

        Ok(Record::LOC {
            size,
            horizontal_precision,
            vertical_precision,
            latitude,
            longitude,
            altitude,
        })
    }

    fn read_mx(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::mx";
        let preference = read_u16(c)?;
        trace!(T, "Parsed preference -> {:?}", preference);

        let (exchange, exchange_length) = Labels::read(c)?;
        trace!(T, "Parsed exchange -> {:?}", exchange);

        let length_after_labels = 2 + exchange_length;
        if stated_length == length_after_labels {
            trace!(T, "Length is correct");
            Ok(Record::MX { preference, exchange })
        } else {
            warn!(T, "Length is incorrect (stated length {}, preference plus exchange length {}", stated_length, length_after_labels);
            Err(WireError::WrongLabelLength {
                stated_length,
                length_after_labels,
            })
        }
    }

    fn read_naptr(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::naptr";
        let order = read_u16(c)?;
        trace!(T, "Parsed order -> {:?}", order);

        let preference = read_u16(c)?;
        trace!(T, "Parsed preference -> {:?}", preference);

        let flags_length = read_u8(c)?;
        trace!(T, "Parsed flags length -> {:?}", flags_length);
        let flags = read_bytes(c, usize::from(flags_length))?;
        trace!(T, "Parsed flags -> {:?}", lossy(&flags));

        let service_length = read_u8(c)?;
        trace!(T, "Parsed service length -> {:?}", service_length);
        let service = read_bytes(c, usize::from(service_length))?;
        trace!(T, "Parsed service -> {:?}", lossy(&service));

        let regex_length = read_u8(c)?;
        trace!(T, "Parsed regex length -> {:?}", regex_length);
        let regex = read_bytes(c, usize::from(regex_length))?;
        trace!(T, "Parsed regex -> {:?}", lossy(&regex));

        let (replacement, replacement_length) = Labels::read(c)?;
        trace!(T, "Parsed replacement -> {:?}", replacement);

        let length_after_labels = 2
            + 2
            + 1
            + u16::from(flags_length)
            + 1
            + u16::from(service_length)
            + 1
            + u16::from(regex_length)
            + replacement_length;
        if stated_length == length_after_labels {
            Ok(Record::NAPTR {
                order,
                preference,
                flags,
                service,
                regex,
                replacement,
            })
        } else {
            Err(WireError::WrongLabelLength {
                stated_length,
                length_after_labels,
            })
        }
    }

    fn read_ns(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::ns";
        let (nameserver, nameserver_length) = Labels::read(c)?;
        trace!(T, "Parsed nameserver -> {:?}", nameserver);

        if stated_length == nameserver_length {
            trace!(T, "Length is correct");
            Ok(Record::NS { nameserver })
        } else {
            warn!(T, "Length is incorrect (stated length {}, nameserver length {}", stated_length, nameserver_length);
            Err(WireError::WrongLabelLength {
                stated_length,
                length_after_labels: nameserver_length,
            })
        }
    }

    fn read_openpgpkey(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::openpgpkey";
        if stated_length == 0 {
            return Err(WireError::WrongRecordLength {
                stated_length,
                mandated_length: MandatedLength::AtLeast(1),
            });
        }
        let key = read_bytes(c, usize::from(stated_length))?;
        trace!(T, "Parsed key -> [\n]");
        Ok(Record::OPENPGPKEY { key })
    }

    fn read_ptr(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::ptr";
        let (cname, cname_length) = Labels::read(c)?;
        trace!(T, "Parsed cname -> {:?}", cname);

        if stated_length == cname_length {
            trace!(T, "Length is correct");
            Ok(Record::PTR { cname })
        } else {
            warn!(T, "Length is incorrect (stated length {}, cname length {}", stated_length, cname_length);
            Err(WireError::WrongLabelLength {
                stated_length,
                length_after_labels: cname_length,
            })
        }
    }

    fn read_soa(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::soa";
        let (mname, mname_length) = Labels::read(c)?;
        trace!(T, "Parsed mname -> {:?}", mname);

        let (rname, rname_length) = Labels::read(c)?;
        trace!(T, "Parsed rname -> {:?}", rname);

        let serial = read_u32(c)?;
        trace!(T, "Parsed serial -> {:?}", serial);

        let refresh_interval = read_u32(c)?;
        trace!(T, "Parsed refresh interval -> {:?}", refresh_interval);

        let retry_interval = read_u32(c)?;
        trace!(T, "Parsed retry interval -> {:?}", retry_interval);

        let expire_limit = read_u32(c)?;
        trace!(T, "Parsed expire limit -> {:?}", expire_limit);

        let minimum_ttl = read_u32(c)?;
        trace!(T, "Parsed minimum TTL -> {:?}", minimum_ttl);

        let length_after_labels = mname_length + rname_length + 4 * 5;
        if stated_length == length_after_labels {
            trace!(T, "Length is correct");
            Ok(Record::SOA {
                mname,
                rname,
                serial,
                refresh_interval,
                retry_interval,
                expire_limit,
                minimum_ttl,
            })
        } else {
            warn!(T, "Length is incorrect (stated length {}, mname plus rname plus fields length {})", stated_length, length_after_labels);
            Err(WireError::WrongLabelLength {
                stated_length,
                length_after_labels,
            })
        }
    }

    fn read_srv(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::srv";
        let priority = read_u16(c)?;
        trace!(T, "Parsed priority -> {:?}", priority);

        let weight = read_u16(c)?;
        trace!(T, "Parsed weight -> {:?}", weight);

        let port = read_u16(c)?;
        trace!(T, "Parsed port -> {:?}", port);

        let (target, target_length) = Labels::read(c)?;
        trace!(T, "Parsed target -> {:?}", target);

        let length_after_labels = 3 * 2 + target_length;
        if stated_length == length_after_labels {
            trace!(T, "Length is correct");
            Ok(Record::SRV {
                priority,
                weight,
                port,
                target,
            })
        } else {
            warn!(T, "Length is incorrect (stated length {}, fields plus target length {})", stated_length, length_after_labels);
            Err(WireError::WrongLabelLength {
                stated_length,
                length_after_labels,
            })
        }
    }

    fn read_sshfp(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::sshfp";
        let algorithm = read_u8(c)?;
        trace!(T, "Parsed algorithm -> {:?}", algorithm);

        let fingerprint_type = read_u8(c)?;
        trace!(T, "Parsed fingerprint type -> {:?}", fingerprint_type);

        if stated_length <= 2 {
            return Err(WireError::WrongRecordLength {
                stated_length,
                mandated_length: MandatedLength::AtLeast(3),
            });
        }

        let fingerprint = read_bytes(c, usize::from(stated_length - 2))?;
        trace!(T, "Parsed fingerprint -> [\n]");

        Ok(Record::SSHFP {
            algorithm,
            fingerprint_type,
            fingerprint,
        })
    }

    fn read_tlsa(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::tlsa";
        let certificate_usage = read_u8(c)?;
        trace!(T, "Parsed certificate_usage -> {:?}", certificate_usage);

        let selector = read_u8(c)?;
        trace!(T, "Parsed selector -> {:?}", selector);

        let matching_type = read_u8(c)?;
        trace!(T, "Parsed matching type -> {:?}", matching_type);

        if stated_length <= 3 {
            return Err(WireError::WrongRecordLength {
                stated_length,
                mandated_length: MandatedLength::AtLeast(4),
            });
        }

        let certificate_data = read_bytes(c, usize::from(stated_length - 3))?;
        trace!(T, "Parsed fingerprint -> [\n]");

        Ok(Record::TLSA {
            certificate_usage,
            selector,
            matching_type,
            certificate_data,
        })
    }

    fn read_txt(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::txt";
        let mut messages = Vec::new();
        let mut total_length: u16 = 0;

        loop {
            let mut message = Vec::new();
            loop {
                let next_length = read_u8(c)?;
                total_length = total_length.wrapping_add(u16::from(next_length)).wrapping_add(1);
                trace!(T, "Parsed slice length -> {:?} (total so far {:?})", next_length, total_length);

                let chunk = read_bytes(c, usize::from(next_length))?;
                message.extend_from_slice(&chunk);

                if next_length < 255 {
                    break;
                }
            }
            trace!(T, "Parsed message -> {:?}", lossy(&message));
            messages.push(message);

            if total_length >= stated_length {
                break;
            }
        }

        if stated_length == total_length {
            trace!(T, "Length is correct");
            Ok(Record::TXT { messages })
        } else {
            warn!(T, "Length is incorrect (stated length {}, messages length {})", stated_length, total_length);
            Err(WireError::WrongLabelLength {
                stated_length,
                length_after_labels: total_length,
            })
        }
    }

    fn read_uri(stated_length: u16, c: &mut Cursor<&[u8]>) -> Result<Record, WireError> {
        const T: &str = "dns::record::uri";
        let priority = read_u16(c)?;
        trace!(T, "Parsed priority -> {:?}", priority);

        let weight = read_u16(c)?;
        trace!(T, "Parsed weight -> {:?}", weight);

        if stated_length <= 4 {
            return Err(WireError::WrongRecordLength {
                stated_length,
                mandated_length: MandatedLength::AtLeast(5),
            });
        }

        let target = read_bytes(c, usize::from(stated_length - 4))?;
        trace!(T, "Parsed target -> {:?}", lossy(&target));

        Ok(Record::URI {
            priority,
            weight,
            target,
        })
    }

    /// The record type of this record.
    pub fn record_type(&self) -> RecordType {
        match self {
            Record::A { .. } => RecordType::A,
            Record::AAAA { .. } => RecordType::AAAA,
            Record::CAA { .. } => RecordType::CAA,
            Record::CNAME { .. } => RecordType::CNAME,
            Record::EUI48 { .. } => RecordType::EUI48,
            Record::EUI64 { .. } => RecordType::EUI64,
            Record::HINFO { .. } => RecordType::HINFO,
            Record::LOC { .. } => RecordType::LOC,
            Record::MX { .. } => RecordType::MX,
            Record::NAPTR { .. } => RecordType::NAPTR,
            Record::NS { .. } => RecordType::NS,
            Record::OPENPGPKEY { .. } => RecordType::OPENPGPKEY,
            Record::PTR { .. } => RecordType::PTR,
            Record::SOA { .. } => RecordType::SOA,
            Record::SRV { .. } => RecordType::SRV,
            Record::SSHFP { .. } => RecordType::SSHFP,
            Record::TLSA { .. } => RecordType::TLSA,
            Record::TXT { .. } => RecordType::TXT,
            Record::URI { .. } => RecordType::URI,
            Record::Other { type_number, .. } => RecordType::Other(*type_number),
        }
    }

    /// The human-readable summary of this record's contents.
    pub fn summary(&self, format_duration: &dyn Fn(u32) -> String) -> String {
        match self {
            Record::A { address } => address.to_string(),
            Record::AAAA { address } => address.to_string(),
            Record::CAA { critical, tag, value } => format!(
                "{} {} ({})",
                quoted_bytes(tag),
                quoted_bytes(value),
                if *critical { "critical" } else { "non-critical" }
            ),
            Record::CNAME { domain } => format!("{:?}", domain.to_string()),
            Record::EUI48 { octets } => format!("\"{}\"", hyphenated_hex(octets)),
            Record::EUI64 { octets } => format!("\"{}\"", hyphenated_hex(octets)),
            Record::HINFO { cpu, os } => format!("{} {}", quoted_bytes(cpu), quoted_bytes(os)),
            Record::LOC {
                size,
                horizontal_precision,
                vertical_precision,
                latitude,
                longitude,
                altitude,
            } => format!(
                "{} ({}, {}) ({}, {}, {})",
                loc_size_string(*size),
                horizontal_precision,
                vertical_precision,
                position_string(latitude),
                position_string(longitude),
                altitude.to_string()
            ),
            Record::MX { preference, exchange } => {
                format!("{} {:?}", preference, exchange.to_string())
            }
            Record::NAPTR {
                order,
                preference,
                flags,
                service,
                regex,
                replacement,
            } => format!(
                "{} {} {} {} {} {:?}",
                order,
                preference,
                quoted_bytes(flags),
                quoted_bytes(service),
                quoted_bytes(regex),
                replacement.to_string()
            ),
            Record::NS { nameserver } => format!("{:?}", nameserver.to_string()),
            Record::OPENPGPKEY { key } => format!("\"{}\"", base64(key)),
            Record::PTR { cname } => format!("{:?}", cname.to_string()),
            Record::SOA {
                mname,
                rname,
                serial,
                refresh_interval,
                retry_interval,
                expire_limit,
                minimum_ttl,
            } => format!(
                "{:?} {:?} {} {} {} {} {}",
                mname.to_string(),
                rname.to_string(),
                serial,
                format_duration(*refresh_interval),
                format_duration(*retry_interval),
                format_duration(*expire_limit),
                format_duration(*minimum_ttl)
            ),
            Record::SRV {
                priority,
                weight,
                port,
                target,
            } => format!("{} {} {:?}:{}", priority, weight, target.to_string(), port),
            Record::SSHFP {
                algorithm,
                fingerprint_type,
                fingerprint,
            } => format!("{} {} {}", algorithm, fingerprint_type, hex(fingerprint)),
            Record::TLSA {
                certificate_usage,
                selector,
                matching_type,
                certificate_data,
            } => format!(
                "{} {} {} \"{}\"",
                certificate_usage,
                selector,
                matching_type,
                hex(certificate_data)
            ),
            Record::TXT { messages } => messages
                .iter()
                .map(|m| quoted_bytes(m))
                .collect::<Vec<_>>()
                .join(", "),
            Record::URI {
                priority,
                weight,
                target,
            } => format!("{} {} {}", priority, weight, quoted_bytes(target)),
            Record::Other { bytes, .. } => format!("{:?}", bytes),
        }
    }

    /// The JSON representation of this record's data.
    pub fn json_data(&self) -> String {
        let mut o = JsonObject::new();
        match self {
            Record::A { address } => {
                o.string("address", &address.to_string());
            }
            Record::AAAA { address } => {
                o.string("address", &address.to_string());
            }
            Record::CAA { critical, tag, value } => {
                o.bool("critical", *critical);
                o.string("tag", &lossy(tag));
                o.string("value", &lossy(value));
            }
            Record::CNAME { domain } => {
                o.string("domain", &domain.to_string());
            }
            Record::EUI48 { octets } => {
                o.string("identifier", &hyphenated_hex(octets));
            }
            Record::EUI64 { octets } => {
                o.string("identifier", &hyphenated_hex(octets));
            }
            Record::HINFO { cpu, os } => {
                o.string("cpu", &lossy(cpu));
                o.string("os", &lossy(os));
            }
            Record::LOC {
                size,
                horizontal_precision,
                vertical_precision,
                latitude,
                longitude,
                altitude,
            } => {
                o.string("size", &loc_size_string(*size));
                let mut precision = JsonObject::new();
                precision.number("horizontal", u64::from(*horizontal_precision));
                precision.number("vertical", u64::from(*vertical_precision));
                o.raw("precision", &precision.finish());
                let mut point = JsonObject::new();
                match latitude {
                    Some(p) => point.string("latitude", &p.to_string()),
                    None => point.raw("latitude", "null"),
                }
                match longitude {
                    Some(p) => point.string("longitude", &p.to_string()),
                    None => point.raw("longitude", "null"),
                }
                point.string("altitude", &altitude.to_string());
                o.raw("point", &point.finish());
            }
            Record::MX { preference, exchange } => {
                o.number("preference", u64::from(*preference));
                o.string("exchange", &exchange.to_string());
            }
            Record::NAPTR {
                order,
                flags,
                service,
                regex,
                replacement,
                ..
            } => {
                o.number("order", u64::from(*order));
                o.string("flags", &lossy(flags));
                o.string("service", &lossy(service));
                o.string("regex", &lossy(regex));
                o.string("replacement", &replacement.to_string());
            }
            Record::NS { nameserver } => {
                o.string("nameserver", &nameserver.to_string());
            }
            Record::OPENPGPKEY { key } => {
                o.string("key", &base64(key));
            }
            Record::PTR { cname } => {
                o.string("cname", &cname.to_string());
            }
            Record::SOA { mname, .. } => {
                o.string("mname", &mname.to_string());
            }
            Record::SRV {
                priority,
                weight,
                port,
                target,
            } => {
                o.number("priority", u64::from(*priority));
                o.number("weight", u64::from(*weight));
                o.number("port", u64::from(*port));
                o.string("target", &target.to_string());
            }
            Record::SSHFP {
                algorithm,
                fingerprint_type,
                fingerprint,
            } => {
                o.number("algorithm", u64::from(*algorithm));
                o.number("fingerprint_type", u64::from(*fingerprint_type));
                o.string("fingerprint", &hex(fingerprint));
            }
            Record::TLSA {
                certificate_usage,
                selector,
                matching_type,
                certificate_data,
            } => {
                o.number("certificate_usage", u64::from(*certificate_usage));
                o.number("selector", u64::from(*selector));
                o.number("matching_type", u64::from(*matching_type));
                o.string("certificate_data", &hex(certificate_data));
            }
            Record::TXT { messages } => {
                let strings: Vec<String> = messages.iter().map(|m| json::string(&lossy(m))).collect();
                o.raw("messages", &format!("[{}]", strings.join(",")));
            }
            Record::URI {
                priority,
                weight,
                target,
            } => {
                o.number("priority", u64::from(*priority));
                o.number("weight", u64::from(*weight));
                o.string("target", &lossy(target));
            }
            Record::Other { bytes, .. } => {
                o.raw("bytes", &json::byte_array(bytes));
            }
        }
        o.finish()
    }
}

fn position_string(position: &Option<Position>) -> String {
    match position {
        Some(p) => p.to_string(),
        None => "Out of range".to_string(),
    }
}

/// Formats bytes the way DNS text strings are shown: quoted, with quotes
/// and backslashes escaped, and non-printable bytes as decimal escapes.
pub fn quoted_bytes(bytes: &[u8]) -> String {
    let mut out = String::with_capacity(bytes.len() + 2);
    out.push('"');
    for &b in bytes {
        match b {
            b'"' => out.push_str("\\\""),
            b'\\' => out.push_str("\\\\"),
            0x20..=0x7F => out.push(b as char),
            _ => {
                let _ = write!(out, "\\{}", b);
            }
        }
    }
    out.push('"');
    out
}

pub fn hex(bytes: &[u8]) -> String {
    let mut out = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        let _ = write!(out, "{:02x}", b);
    }
    out
}

fn hyphenated_hex(bytes: &[u8]) -> String {
    bytes
        .iter()
        .map(|b| format!("{:02x}", b))
        .collect::<Vec<_>>()
        .join("-")
}

pub fn base64(bytes: &[u8]) -> String {
    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity((bytes.len() + 2) / 3 * 4);
    for chunk in bytes.chunks(3) {
        let b0 = chunk[0];
        let b1 = chunk.get(1).copied().unwrap_or(0);
        let b2 = chunk.get(2).copied().unwrap_or(0);
        out.push(TABLE[(b0 >> 2) as usize] as char);
        out.push(TABLE[(((b0 & 0b11) << 4) | (b1 >> 4)) as usize] as char);
        if chunk.len() > 1 {
            out.push(TABLE[(((b1 & 0b1111) << 2) | (b2 >> 6)) as usize] as char);
        } else {
            out.push('=');
        }
        if chunk.len() > 2 {
            out.push(TABLE[(b2 & 0b11_1111) as usize] as char);
        } else {
            out.push('=');
        }
    }
    out
}
