}

/// Builds a JSON object with fields in the order they were added.
pub struct JsonObject {
    fields: Vec<String>,
}

impl JsonObject {
    pub fn new() -> Self {
        JsonObject { fields: Vec::new() }
    }

    pub fn raw(&mut self, key: &str, value: &str) -> &mut Self {
        self.fields.push(format!("{}:{}", string(key), value));
        self
    }

    pub fn string(&mut self, key: &str, value: &str) -> &mut Self {
        let v = string(value);
        self.raw(key, &v)
    }

    pub fn number(&mut self, key: &str, value: u64) -> &mut Self {
        let v = value.to_string();
        self.raw(key, &v)
    }

    pub fn bool(&mut self, key: &str, value: bool) -> &mut Self {
        self.raw(key, if value { "true" } else { "false" })
    }

    pub fn finish(&self) -> String {
        format!("{{{}}}", self.fields.join(","))
    }
}

/// Serialises a list of already-serialised JSON values.
pub fn array(items: &[String]) -> String {
    format!("[{}]", items.join(","))
}
