//! The ways of sending a DNS request and receiving a response.

use std::fmt;
use std::io;

use crate::dns::{Request, Response, WireError};

pub mod auto;
pub mod httparse;
pub mod https;
pub mod openssl;
pub mod tcp;
pub mod tls;
pub mod udp;

/// Something that can send a request and receive a response.
pub trait Transport {
    fn send(&self, request: &Request) -> Result<Response, Error>;
}

/// Something that can go wrong while making a request.
#[derive(Debug)]
pub enum Error {
    /// An I/O error.
    NetworkError(io::Error),
    /// A response that could not be decoded.
    WireError(WireError),
    /// The TCP connection closed before any data arrived.
    TruncatedResponse,
    /// An error from the TLS layer.
    TlsError(String),
    /// An error from the HTTP layer.
    HttpError(String),
    /// The HTTPS nameserver returned a non-200 status.
    WrongHttpStatus(u16, String),
}

impl From<io::Error> for Error {
    fn from(e: io::Error) -> Self {
        Error::NetworkError(e)
    }
}

impl From<WireError> for Error {
    fn from(e: WireError) -> Self {
        Error::WireError(e)
    }
}

impl Error {
    /// The phase in which this error happened, for error messages.
    pub fn phase(&self) -> &'static str {
        match self {
            Error::NetworkError(_) | Error::TruncatedResponse => "network",
            Error::WireError(_) => "protocol",
            Error::TlsError(_) => "tls",
            Error::HttpError(_) | Error::WrongHttpStatus(..) => "http",
        }
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::NetworkError(e) => write!(f, "{}", e),
            Error::WireError(e) => write!(f, "{}", e),
            Error::TruncatedResponse => write!(f, "Truncated response"),
            Error::TlsError(e) => write!(f, "{}", e),
            Error::HttpError(e) => write!(f, "{}", e),
            Error::WrongHttpStatus(code, reason) => {
                write!(f, "Nameserver returned HTTP {} ({})", code, reason)
            }
        }
    }
}

/// Reads a length-prefixed DNS response from a stream (TCP or TLS).
pub fn read_length_prefixed(stream: &mut dyn io::Read) -> Result<Response, Error> {
    const T: &str = "dns_transport::tcp";
    info!(T, "Waiting to receive...");

    let mut buf = [0u8; 4096];
    let read_len = stream.read(&mut buf)?;

    if read_len == 0 {
        return Err(Error::TruncatedResponse);
    } else if read_len == 1 {
        info!(T, "Received one byte of data");
    } else {
        info!(T, "Received {} bytes of data", read_len);
    }

    let total_len = usize::from(u16::from_be_bytes([buf[0], buf[1]]));

    if total_len > read_len.wrapping_sub(2) {
        debug!(T, "We need to read {} bytes total", total_len);
        let mut combined = buf[2..read_len].to_vec();
        while combined.len() < total_len {
            let mut extra = [0u8; 4096];
            let extra_len = stream.read(&mut extra)?;
            info!(T, "Received further {} bytes of data (of {})", extra_len, total_len);
            combined.extend_from_slice(&extra[..extra_len]);
        }
        let response = Response::from_bytes(&combined)?;
        Ok(response)
    } else {
        debug!(T, "We have enough bytes");
        let slice: &[u8] = if read_len >= 2 { &buf[2..read_len] } else { &[] };
        let response = Response::from_bytes(slice)?;
        Ok(response)
    }
}
