//! A thin binding to the system OpenSSL library, used for the TLS and
//! HTTPS transports. Error messages are rendered in the classic
//! `error:CODE:lib:func:reason:file:line:` style.

#![allow(non_camel_case_types)]

use std::ffi::{CStr, CString};
use std::io::{self, Read, Write};
use std::net::{IpAddr, TcpStream};
use std::os::raw::{c_char, c_int, c_long, c_uint, c_ulong, c_void};
use std::os::unix::io::AsRawFd;

pub enum SSL_CTX {}
pub enum SSL {}
pub enum SSL_METHOD {}
pub enum X509_VERIFY_PARAM {}

#[link(name = "ssl")]
#[link(name = "crypto")]
extern "C" {
    fn TLS_client_method() -> *const SSL_METHOD;
    fn SSL_CTX_new(method: *const SSL_METHOD) -> *mut SSL_CTX;
    fn SSL_CTX_free(ctx: *mut SSL_CTX);
    fn SSL_CTX_set_default_verify_paths(ctx: *mut SSL_CTX) -> c_int;
    fn SSL_CTX_set_verify(ctx: *mut SSL_CTX, mode: c_int, callback: *const c_void);
    fn SSL_new(ctx: *mut SSL_CTX) -> *mut SSL;
    fn SSL_free(ssl: *mut SSL);
    fn SSL_set_fd(ssl: *mut SSL, fd: c_int) -> c_int;
    fn SSL_ctrl(ssl: *mut SSL, cmd: c_int, larg: c_long, parg: *mut c_void) -> c_long;
    fn SSL_get0_param(ssl: *mut SSL) -> *mut X509_VERIFY_PARAM;
    fn X509_VERIFY_PARAM_set_hostflags(param: *mut X509_VERIFY_PARAM, flags: c_uint);
    fn X509_VERIFY_PARAM_set1_host(
        param: *mut X509_VERIFY_PARAM,
        name: *const c_char,
        namelen: usize,
    ) -> c_int;
    fn X509_VERIFY_PARAM_set1_ip_asc(param: *mut X509_VERIFY_PARAM, ipasc: *const c_char) -> c_int;
    fn SSL_connect(ssl: *mut SSL) -> c_int;
    fn SSL_get_error(ssl: *const SSL, ret: c_int) -> c_int;
    fn SSL_get_verify_result(ssl: *const SSL) -> c_long;
    fn X509_verify_cert_error_string(n: c_long) -> *const c_char;
    fn ERR_get_error() -> c_ulong;
    fn ERR_clear_error();
    fn ERR_reason_error_string(e: c_ulong) -> *const c_char;
    fn SSL_read(ssl: *mut SSL, buf: *mut c_void, num: c_int) -> c_int;
    fn SSL_write(ssl: *mut SSL, buf: *const c_void, num: c_int) -> c_int;
}

const SSL_VERIFY_PEER: c_int = 1;
const SSL_CTRL_SET_TLSEXT_HOSTNAME: c_int = 55;
const TLSEXT_NAMETYPE_HOST_NAME: c_long = 0;
const X509_CHECK_FLAG_NO_PARTIAL_WILDCARDS: c_uint = 0x8;

const SSL_ERROR_SSL: c_int = 1;
const SSL_ERROR_WANT_READ: c_int = 2;
const SSL_ERROR_WANT_WRITE: c_int = 3;
const SSL_ERROR_SYSCALL: c_int = 5;
const SSL_ERROR_ZERO_RETURN: c_int = 6;

const SSL_R_UNEXPECTED_EOF_WHILE_READING: c_ulong = 294;

fn cstr(ptr: *const c_char) -> String {
    if ptr.is_null() {
        String::new()
    } else {
        unsafe { CStr::from_ptr(ptr) }.to_string_lossy().into_owned()
    }
}

/// A connector that holds a configured context.
pub struct TlsConnector {
    ctx: *mut SSL_CTX,
}

/// A TLS session over a TCP stream.
pub struct TlsStream {
    ssl: *mut SSL,
    _stream: TcpStream,
}

/// The reason a handshake failed, rendered as text.
pub struct HandshakeError(pub String);

impl TlsConnector {
    pub fn new() -> Result<Self, String> {
        unsafe {
            ERR_clear_error();
            let method = TLS_client_method();
            let ctx = SSL_CTX_new(method);
            if ctx.is_null() {
                return Err(error_stack_string(None));
            }
            if SSL_CTX_set_default_verify_paths(ctx) != 1 {
                let e = error_stack_string(None);
                SSL_CTX_free(ctx);
                return Err(e);
            }
            SSL_CTX_set_verify(ctx, SSL_VERIFY_PEER, std::ptr::null());
            Ok(TlsConnector { ctx })
        }
    }

    pub fn connect(&self, domain: &str, stream: TcpStream) -> Result<TlsStream, HandshakeError> {
        unsafe {
            ERR_clear_error();
            let ssl = SSL_new(self.ctx);
            if ssl.is_null() {
                return Err(HandshakeError(error_stack_string(None)));
            }

            let is_ip = domain.parse::<IpAddr>().is_ok();
            if !is_ip {
                if let Ok(c) = CString::new(domain) {
                    SSL_ctrl(
                        ssl,
                        SSL_CTRL_SET_TLSEXT_HOSTNAME,
                        TLSEXT_NAMETYPE_HOST_NAME,
                        c.as_ptr() as *mut c_void,
                    );
                }
            }

            let param = SSL_get0_param(ssl);
            X509_VERIFY_PARAM_set_hostflags(param, X509_CHECK_FLAG_NO_PARTIAL_WILDCARDS);
            if let Ok(c) = CString::new(domain) {
                if is_ip {
                    X509_VERIFY_PARAM_set1_ip_asc(param, c.as_ptr());
                } else {
                    X509_VERIFY_PARAM_set1_host(param, c.as_ptr(), domain.len());
                }
            }

            if SSL_set_fd(ssl, stream.as_raw_fd()) != 1 {
                let e = error_stack_string(None);
                SSL_free(ssl);
                return Err(HandshakeError(e));
            }

            let ret = SSL_connect(ssl);
            if ret == 1 {
                return Ok(TlsStream { ssl, _stream: stream });
            }

            let code = SSL_get_error(ssl, ret);
            let verify = SSL_get_verify_result(ssl);
            let message = match code {
                SSL_ERROR_SSL => {
                    let e = ERR_get_error();
                    let reason = reason_code(e);
                    if reason == SSL_R_UNEXPECTED_EOF_WHILE_READING {
                        "unexpected EOF".to_string()
                    } else {
                        let stack = error_stack_string(Some(e));
                        if verify != 0 {
                            format!("{} ({})", stack, verify_result_string(verify))
                        } else {
                            stack
                        }
                    }
                }
                SSL_ERROR_SYSCALL => {
                    let os = io::Error::last_os_error();
                    if os.raw_os_error().unwrap_or(0) == 0 {
                        "unexpected EOF".to_string()
                    } else {
                        os.to_string()
                    }
                }
                SSL_ERROR_ZERO_RETURN => "the SSL session has been shut down".to_string(),
                SSL_ERROR_WANT_READ | SSL_ERROR_WANT_WRITE => "the operation should be retried".to_string(),
                other => format!("unknown error code {}", other),
            };
            SSL_free(ssl);
            Err(HandshakeError(message))
        }
    }
}

impl Drop for TlsConnector {
    fn drop(&mut self) {
        unsafe { SSL_CTX_free(self.ctx) }
    }
}

impl Drop for TlsStream {
    fn drop(&mut self) {
        unsafe { SSL_free(self.ssl) }
    }
}

impl Read for TlsStream {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if buf.is_empty() {
            return Ok(0);
        }
        loop {
            unsafe {
                ERR_clear_error();
                let len = buf.len().min(c_int::MAX as usize) as c_int;
                let ret = SSL_read(self.ssl, buf.as_mut_ptr() as *mut c_void, len);
                if ret > 0 {
                    return Ok(ret as usize);
                }
                let code = SSL_get_error(self.ssl, ret);
                match code {
                    SSL_ERROR_ZERO_RETURN => return Ok(0),
                    SSL_ERROR_WANT_READ | SSL_ERROR_WANT_WRITE => continue,
                    SSL_ERROR_SYSCALL => {
                        let os = io::Error::last_os_error();
                        if os.raw_os_error().unwrap_or(0) == 0 {
                            return Ok(0);
                        }
                        return Err(os);
                    }
                    SSL_ERROR_SSL => {
                        let e = ERR_get_error();
                        if reason_code(e) == SSL_R_UNEXPECTED_EOF_WHILE_READING {
                            return Ok(0);
                        }
                        return Err(io::Error::new(io::ErrorKind::Other, error_stack_string(Some(e))));
                    }
                    other => {
                        return Err(io::Error::new(
                            io::ErrorKind::Other,
                            format!("unknown error code {}", other),
                        ))
                    }
                }
            }
        }
    }
}

impl Write for TlsStream {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        if buf.is_empty() {
            return Ok(0);
        }
        loop {
            unsafe {
                ERR_clear_error();
                let len = buf.len().min(c_int::MAX as usize) as c_int;
                let ret = SSL_write(self.ssl, buf.as_ptr() as *const c_void, len);
                if ret > 0 {
                    return Ok(ret as usize);
                }
                let code = SSL_get_error(self.ssl, ret);
                match code {
                    SSL_ERROR_WANT_READ | SSL_ERROR_WANT_WRITE => continue,
                    SSL_ERROR_SYSCALL => {
                        let os = io::Error::last_os_error();
                        if os.raw_os_error().unwrap_or(0) == 0 {
                            return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "unexpected EOF"));
                        }
                        return Err(os);
                    }
                    SSL_ERROR_ZERO_RETURN => {
                        return Err(io::Error::new(
                            io::ErrorKind::Other,
                            "the SSL session has been shut down",
                        ))
                    }
                    _ => {
                        let e = ERR_get_error();
                        return Err(io::Error::new(io::ErrorKind::Other, error_stack_string(Some(e))));
                    }
                }
            }
        }
    }

    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}

fn reason_code(e: c_ulong) -> c_ulong {
    if e & 0x8000_0000 != 0 {
        e & 0x7FFF_FFFF
    } else {
        e & 0x7F_FFFF
    }
}

fn lib_code(e: c_ulong) -> c_ulong {
    (e >> 23) & 0xFF
}

/// Details of where a given error reason is raised, in the classic layout.
struct ErrorSite {
    func_code: u32,
    func_name: &'static str,
    file: &'static str,
    line: u32,
}

fn ssl_error_site(reason: c_ulong) -> ErrorSite {
