    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if buf.is_empty() {
            return Ok(0);
        }
        loop {
            unsafe {
                ERR_clear_error();
                let len = buf.len().min(c_int::MAX as usize) as c_int;
                let ret = SSL_read(self.ssl, buf.as_mut_ptr() as *mut c_void, len);
                if ret > 0 {
                    return Ok(ret as usize);
                }
                let code = SSL_get_error(self.ssl, ret);
                match code {
                    SSL_ERROR_ZERO_RETURN => return Ok(0),
                    SSL_ERROR_WANT_READ | SSL_ERROR_WANT_WRITE => continue,
                    SSL_ERROR_SYSCALL => {
                        let os = io::Error::last_os_error();
                        if os.raw_os_error().unwrap_or(0) == 0 {
                            return Ok(0);
                        }
                        return Err(os);
                    }
                    SSL_ERROR_SSL => {
                        let e = ERR_get_error();
                        if reason_code(e) == SSL_R_UNEXPECTED_EOF_WHILE_READING {
                            return Ok(0);
                        }
                        return Err(io::Error::new(io::ErrorKind::Other, error_stack_string(Some(e))));
                    }
                    other => {
                        return Err(io::Error::new(
                            io::ErrorKind::Other,
                            format!("unknown error code {}", other),
                        ))
                    }
                }
            }
        }
    }
