use std::io::Write;
use std::net::TcpStream;

use super::openssl::TlsConnector;
use super::tcp::length_prefixed_bytes;
use super::{read_length_prefixed, Error, Transport};
use crate::dns::{Request, Response};

const T: &str = "dns_transport::tls";

/// Sends requests over DNS-over-TLS.
pub struct TlsTransport {
    addr: String,
}

impl TlsTransport {
    pub fn new(addr: String) -> Self {
        TlsTransport { addr }
    }

    /// Splits the nameserver into a domain and a port.
    fn split_domain(&self) -> (String, u16) {
        let domain = self.addr.split(':').next().unwrap_or("").to_string();
        let port = match self.addr.rfind(':') {
            Some(index) => {
                let port_str = &self.addr[index + 1..];
                match port_str.parse::<u16>() {
                    Ok(p) => p,
                    Err(e) => crate::fake_panic(
                        "dns-transport/src/tls.rs:41:65",
                        &format!("Invalid port number: {:?}", e),
                    ),
                }
            }
            None => 853,
        };
        (domain, port)
    }
}

impl Transport for TlsTransport {
    fn send(&self, request: &Request) -> Result<Response, Error> {
        info!(T, "Opening TLS socket");
        let connector = TlsConnector::new().map_err(Error::TlsError)?;

        let (domain, port) = self.split_domain();
        info!(T, "Connecting using domain {:?}", domain);

        let stream = TcpStream::connect((domain.as_str(), port))?;
        let mut stream = connector
            .connect(&domain, stream)
            .map_err(|e| Error::TlsError(e.0))?;
        debug!(T, "Connected");

        let bytes = length_prefixed_bytes(request);
        info!(T, "Sending {} bytes of data to {} over TLS", bytes.len(), self.addr);
        stream.write_all(&bytes)?;
        debug!(T, "Wrote all bytes");

        read_length_prefixed(&mut stream)
    }
}
