                        println!("Ran in {}ms", d.as_millis());
                    }
                    return true;
                }

                let type_width = rows.iter().map(|r| r.type_text.len()).max().unwrap_or(0);
                let qname_width = rows.iter().map(|r| r.qname.len()).max().unwrap_or(0);
                let ttl_width = rows.iter().map(|r| r.ttl.len()).max().unwrap_or(0);

                for row in &rows {
                    let type_pad = " ".repeat(type_width.saturating_sub(row.type_text.len()));
                    let qname_pad = " ".repeat(qname_width.saturating_sub(row.qname.len()));
                    let ttl_pad = " ".repeat(ttl_width.saturating_sub(row.ttl.len()));
                    let marker = match row.kind {
                        SectionKind::Answer => " ".to_string(),
                        SectionKind::Authority => colours.authority("A"),
                        SectionKind::Additional => colours.additional("+"),
                    };
                    println!(
