                        marker,
                        row.summary
                    );
                }

                if let Some(d) = duration {
                    println!("Ran in {}ms", d.as_millis());
                }
                true
            }
        }
    }

    /// Prints an error that occurred while making a request.
    pub fn print_error(&self, error: &TransportError) {
