//! Loading hostname hints from the system hosts file.

use std::collections::HashMap;
use std::net::IpAddr;

use crate::dns::Labels;

const TARGET: &str = "dog::hints";
const HOSTS_PATH: &str = "/etc/hosts";

/// The hostnames listed in the hosts file, with their addresses.
pub struct Hints {
    entries: HashMap<String, IpAddr>,
}

impl Hints {
    pub fn load() -> Self {
        debug!(TARGET, "Reading hints from {}", HOSTS_PATH);
        let mut entries = HashMap::new();

        match std::fs::read_to_string(HOSTS_PATH) {
            Ok(contents) => {
                for line in contents.lines() {
                    let line = match line.find('#') {
                        Some(index) => &line[..index],
                        None => line,
                    };
                    let mut parts = line.split_whitespace();
                    let ip = match parts.next() {
                        Some(ip) => ip,
                        None => continue,
                    };
                    let ip: IpAddr = match ip.parse() {
                        Ok(ip) => ip,
                        Err(_) => continue,
                    };
                    for hostname in parts {
                        entries.insert(hostname.to_string(), ip);
                    }
                }
                trace!(TARGET, "{} hostname hints loaded OK.", entries.len());
            }
            Err(e) => {
                warn!(TARGET, "Error loading hints from {}: {}", HOSTS_PATH, e);
            }
        }

        Hints { entries }
    }

    /// Whether the given domain appears in the hosts file.
    pub fn contains(&self, domain: &Labels) -> bool {
        let wanted = domain.to_string();
        self.entries.keys().any(|hostname| {
            match Labels::encode(hostname) {
                Ok(labels) => labels.to_string() == wanted,
                Err(_) => format!("{}.", hostname) == wanted,
            }
        })
    }
}
