//! Finding out which nameserver to use.

use std::fmt;
use std::io::{self, BufRead};

use crate::options::ResolverType;

const RESOLV_CONF_PATH: &str = "/etc/resolv.conf";

/// A problem looking up the system's nameservers.
#[derive(Debug)]
pub enum ResolverLookupError {
    Io(io::Error),
    NoNameservers,
}

impl fmt::Display for ResolverLookupError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ResolverLookupError::Io(e) => write!(f, "{}", e),
            ResolverLookupError::NoNameservers => {
                write!(f, "No nameservers found in {}", RESOLV_CONF_PATH)
            }
        }
    }
}

impl ResolverType {
    /// Produces the nameserver address to use.
    pub fn obtain(&self) -> Result<String, ResolverLookupError> {
        match self {
            ResolverType::Specific(ns) => Ok(ns.clone()),
            ResolverType::SystemDefault => system_nameserver(),
        }
    }
}

fn system_nameserver() -> Result<String, ResolverLookupError> {
    let file = std::fs::File::open(RESOLV_CONF_PATH).map_err(ResolverLookupError::Io)?;
    let reader = io::BufReader::new(file);

    for line in reader.lines() {
        let line = line.map_err(ResolverLookupError::Io)?;
        let line = line.trim();
        if let Some(rest) = line.strip_prefix("nameserver") {
            if rest.starts_with(char::is_whitespace) {
                let address = rest.trim();
                if !address.is_empty() {
                    return Ok(address.to_string());
                }
            }
        }
    }

    Err(ResolverLookupError::NoNameservers)
}
EOF
