//! dog, a command-line DNS client.

#![warn(rust_2018_idioms)]

#[macro_use]
mod logger;

mod dns;
mod getopts;
mod help;
mod hints;
mod json;
mod options;
mod output;
mod resolver;
mod transport;

use std::io::Write;
use std::time::Instant;

use dns::{Flags, Labels, OptRecord, Query, Request, Response};
use options::{HelpReason, Options, OptionsResult, OutputFormat, TransportType, TxidGenerator, UseEDNS};
use transport::{
    auto::AutoTransport, https::HttpsTransport, tcp::TcpTransport, tls::TlsTransport,
    udp::UdpTransport, Transport,
};

pub const VERSION_TAG: &str = "v0.2.0-pre";
pub const COMMIT_HASH: &str = "d436ea3b";
pub const BUILD_DATE: &str = "2026-06-11";
pub const HOMEPAGE: &str = "https://dns.lookup.dog/";
pub const USER_AGENT: &str = "dog/0.2.0-pre";

/// Exit statuses.
mod exits {
    pub const SUCCESS: i32 = 0;
    pub const NETWORK_ERROR: i32 = 1;
    pub const NO_SHORT_RESULTS: i32 = 2;
    pub const OPTIONS_ERROR: i32 = 3;
    pub const SYSTEM_ERROR: i32 = 4;
}

/// Prints a message in the style of an unrecoverable runtime failure at
/// the given source location, then aborts the process.
pub fn fake_panic(location: &str, message: &str) -> ! {
    let tid = unsafe { libc::gettid() };
    let text = format!(
        "\nthread 'main' ({}) panicked at {}:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n",
        tid, location, message
    );
    let stderr = std::io::stderr();
    let mut lock = stderr.lock();
    let _ = lock.write_all(text.as_bytes());
    let _ = lock.flush();
    std::process::abort();
}

fn main() {
    logger::init();

    let args: Vec<String> = std::env::args_os()
        .skip(1)
        .map(|a| a.to_string_lossy().into_owned())
        .collect();

    match Options::getopts(args) {
        OptionsResult::Ok(options) => {
            info!("dog", "Running with options -> {:#?}", options);
            std::process::exit(run(options));
        }
        OptionsResult::Help(colours, reason) => {
            print!("{}", help::help_text(colours.should_use_colours()));
            let _ = std::io::stdout().flush();
            match reason {
                HelpReason::Flag => std::process::exit(exits::SUCCESS),
                HelpReason::NoDomains => std::process::exit(exits::OPTIONS_ERROR),
            }
        }
        OptionsResult::Version(colours) => {
            print!("{}", help::version_text(colours.should_use_colours()));
            let _ = std::io::stdout().flush();
            std::process::exit(exits::SUCCESS);
        }
        OptionsResult::InvalidOptionsFormat(fail) => {
            eprintln!("dog: Invalid options: {}", fail);
            std::process::exit(exits::OPTIONS_ERROR);
        }
        OptionsResult::InvalidOptions(error) => {
            eprintln!("dog: Invalid options: {}", error);
            std::process::exit(exits::OPTIONS_ERROR);
        }
    }
}

/// One request to make, with the nameserver and transport to use.
struct RequestPlan {
    request: Request,
    resolver: options::ResolverType,
    transport: TransportType,
}

impl options::RequestGenerator {
    /// Generates every combination of domain, type, class, nameserver, and
    /// transport.
    fn generate(&self) -> Vec<RequestPlan> {
        let mut plans = Vec::new();
        let inputs = &self.inputs;

        for domain in &inputs.domains {
            for &qtype in &inputs.record_types {
                for &qclass in &inputs.classes {
                    for resolver in &inputs.resolver_types {
                        for &transport in &inputs.transport_types {
                            let transaction_id = match self.txid_generator {
                                TxidGenerator::Random => rand::random::<u16>(),
                                TxidGenerator::Sequence(n) => n,
                            };

                            let mut flags = Flags::query();
                            if self.protocol_tweaks.set_authoritative_flag {
                                flags.authoritative = true;
                            }
                            if self.protocol_tweaks.set_authentic_flag {
                                flags.authentic_data = true;
                            }
                            if self.protocol_tweaks.set_checking_disabled_flag {
                                flags.checking_disabled = true;
                            }

                            let additional = match self.edns {
                                UseEDNS::Disable => None,
                                UseEDNS::SendAndHide | UseEDNS::SendAndShow => Some(OptRecord {
                                    udp_payload_size: self.protocol_tweaks.udp_payload_size.unwrap_or(512),
                                    higher_bits: 0,
                                    edns0_version: 0,
                                    flags: 0,
                                    data: Vec::new(),
                                }),
                            };

                            let request = Request {
                                transaction_id,
                                flags,
                                query: Query {
                                    qname: domain.clone(),
                                    qclass,
                                    qtype,
                                },
                                additional,
                            };

                            plans.push(RequestPlan {
                                request,
                                resolver: resolver.clone(),
                                transport,
                            });
                        }
                    }
                }
            }
        }

        plans
    }
}

fn make_transport(transport: TransportType, nameserver: String) -> Box<dyn Transport> {
    match transport {
        TransportType::Automatic => Box::new(AutoTransport::new(nameserver)),
        TransportType::UDP => Box::new(UdpTransport::new(nameserver)),
        TransportType::TCP => Box::new(TcpTransport::new(nameserver)),
        TransportType::TLS => Box::new(TlsTransport::new(nameserver)),
        TransportType::HTTPS => Box::new(HttpsTransport::new(nameserver)),
    }
}

fn run(options: Options) -> i32 {
    let hints = hints::Hints::load();
    for domain in &options.requests.inputs.domains {
        warn_if_in_hints(&hints, domain);
    }

    let show_opt = options.requests.edns == UseEDNS::SendAndShow;
    let mut responses: Vec<Response> = Vec::new();
    let mut errored = false;

    let timer = if options.measure_time {
        Some(Instant::now())
    } else {
        None
    };

    for plan in options.requests.generate() {
        let nameserver = match plan.resolver.obtain() {
            Ok(ns) => ns,
            Err(e) => {
                eprintln!("Error [system]: {}", e);
                return exits::SYSTEM_ERROR;
            }
        };

        let transport = make_transport(plan.transport, nameserver);
        match transport.send(&plan.request) {
            Ok(mut response) => {
                output::filter_opt(&mut response, show_opt);
                responses.push(response);
            }
            Err(e) => {
                options.format.print_error(&e);
                errored = true;
            }
        }
    }

    let duration = timer.map(|t| t.elapsed());

    if !options.format.print(responses, duration) {
        exits::NO_SHORT_RESULTS
    } else if errored {
        exits::NETWORK_ERROR
    } else {
        exits::SUCCESS
    }
}

fn warn_if_in_hints(hints: &hints::Hints, domain: &Labels) {
    if hints.contains(domain) {
        eprintln!("warning: domain '{}' also exists in hosts file", domain);
    }
}

