/// One request to make, with the nameserver and transport to use.
struct RequestPlan {
    request: Request,
    resolver: options::ResolverType,
    transport: TransportType,
}

impl options::RequestGenerator {
    /// Generates every combination of domain, type, class, nameserver, and
    /// transport.
    fn generate(&self) -> Vec<RequestPlan> {
        let mut plans = Vec::new();
        let inputs = &self.inputs;

        for domain in &inputs.domains {
            for &qtype in &inputs.record_types {
                for &qclass in &inputs.classes {
                    for resolver in &inputs.resolver_types {
                        for &transport in &inputs.transport_types {
                            let transaction_id = match self.txid_generator {
                                TxidGenerator::Random => rand::random::<u16>(),
                                TxidGenerator::Sequence(n) => n,
                            };

                            let mut flags = Flags::query();
                            if self.protocol_tweaks.set_authoritative_flag {
                                flags.authoritative = true;
                            }
                            if self.protocol_tweaks.set_authentic_flag {
                                flags.authentic_data = true;
                            }
                            if self.protocol_tweaks.set_checking_disabled_flag {
                                flags.checking_disabled = true;
                            }

                            let additional = match self.edns {
                                UseEDNS::Disable => None,
                                UseEDNS::SendAndHide | UseEDNS::SendAndShow => Some(OptRecord {
                                    udp_payload_size: self.protocol_tweaks.udp_payload_size.unwrap_or(512),
                                    higher_bits: 0,
                                    edns0_version: 0,
                                    flags: 0,
                                    data: Vec::new(),
                                }),
                            };

                            let request = Request {
                                transaction_id,
                                flags,
                                query: Query {
                                    qname: domain.clone(),
                                    qclass,
                                    qtype,
                                },
                                additional,
                            };

                            plans.push(RequestPlan {
                                request,
                                resolver: resolver.clone(),
                                transport,
                            });
                        }
                    }
                }
            }
        }

        plans
    }
}

