enum LabelError {
    PunycodeError,
    ValidityCriteria,
    TooShortForDns,
    TooLongForDns,
}

/// Applies IDNA processing to a single label, producing its ASCII form.
fn encode_label(label: &str) -> Result<String, Vec<LabelError>> {
    let mut errors = Vec::new();

    // Leniently decode a Punycode label first, so that a non-canonical
    // encoding gets re-encoded rather than rejected outright.
    let mut unicode_input = label.to_string();
    if label.to_ascii_lowercase().starts_with("xn--") {
        match punycode_decode(&label[4..]) {
            Some(decoded) => unicode_input = decoded,
            None => {
                errors.push(LabelError::PunycodeError);
                unicode_input = String::new();
            }
        }
    }

    let mut ascii = String::new();
    if !unicode_input.is_empty() {
        let (unicode, unicode_result) = idna::domain_to_unicode(&unicode_input);
        if unicode_result.is_err() {
            errors.push(LabelError::ValidityCriteria);
        } else if unicode.starts_with('-') || unicode.ends_with('-') || unicode.contains('.') {
            errors.push(LabelError::ValidityCriteria);
        }
        match idna::domain_to_ascii(&unicode_input) {
            Ok(a) => ascii = a,
            Err(_) => {
                if !errors.contains(&LabelError::ValidityCriteria) {
                    errors.push(LabelError::ValidityCriteria);
                }
            }
        }
    }

    if ascii.is_empty() {
        errors.push(LabelError::TooShortForDns);
    }
    if ascii.len() > 63 {
        errors.push(LabelError::TooLongForDns);
    }

    if errors.is_empty() {
        Ok(ascii)
    } else {
        Err(errors)
    }
}

impl Labels {
    pub fn root() -> Self {
        Labels { segments: Vec::new() }
    }

    pub fn segments(&self) -> &[(u8, String)] {
        &self.segments
    }

    /// Parses a user-supplied domain name, applying IDNA processing to
    /// each label in turn. Empty labels are skipped.
    pub fn encode(input: &str) -> Result<Self, InvalidDomain> {
        let mut segments = Vec::new();
        for label in input.split('.') {
            if label.is_empty() {
                continue;
            }
            match encode_label(label) {
                Ok(ascii) => segments.push((ascii.len() as u8, ascii)),
                Err(errors) => {
                    warn!(TARGET, "Could not encode label {:?}: Errors({:?})", label, errors);
                    return Err(InvalidDomain);
                }
            }
        }
        Ok(Labels { segments })
    }

